window.UX_CHAPTERS=window.UX_CHAPTERS||{};
window.UX_CHAPTERS["components"]={"id":"components","num":"13","title":"组件库","summary":"第 02 节给了 令牌 ，第 03–10 节给了 页面 ，本节补上中间缺的一层： 可复用的组件词汇表 。 GPUI 迁移后本节的定位变了 （契约 §1.6 / §6.2）：组件库 gpui-component 0.7.3 已经提供 60","group":"页面与组件","kb":137,"sections":41,"h3":["13.0 组件总览","13.1 按钮","尺寸档","状态矩阵","13.2 输入框","几何规格","状态矩阵","13.3 下拉菜单 / 右键上下文菜单","几何规格","项形态矩阵","13.3.1 贴边翻转（E-8 结论与落地方案）","落地方案：yk-ui 统一实现一次","13.4 对话框","几何与层级","行为矩阵","13.5 Toast / 通知条","几何与层级","停留时长与语义","通知条（页内条，不浮层）","13.6 Tooltip","几何与时序","使用边界","13.7 开关 / 滑块 / 复选框 / 单选","几何规格","标签关联与键盘","13.8 滚动条","规格","现状核对","13.9 分页 / 加载更多 / 无限滚动","何时用哪种","几何规格","13.10 徽标 / 标签 / 头像 / 进度条","几何规格","使用位置","13.11 图标清单","建议新增图标预览（15 个：8 本节新增 + 7 与第 12 节重复）","13.12 组件落地映射","13.13 无障碍基线","焦点环 · 键盘顺序","aria-* 映射（语义表）","组件能力核实结论（已归档，2026-10）"],"html":"<section id=\"components\">\n  <div class=\"sec-head\">\n    <h2><span class=\"sec-num\">13</span>组件库</h2>\n    <p>第 02 节给了<b>令牌</b>，第 03–10 节给了<b>页面</b>，本节补上中间缺的一层：<b>可复用的组件词汇表</b>。\n      <b>GPUI 迁移后本节的定位变了</b>（契约 §1.6 / §6.2）：组件库\n      <code>gpui-component 0.7.3</code> 已经提供 60+ 个组件，所以本节<b>不再设计新控件、\n      不再新建样式文件</b>，只做三件事——<b>选用哪个模块</b>、<b>覆盖哪些主题字段</b>、\n      <b>哪些几何 / 行为必须自建</b>。每个组件仍写死四件事：几何规格（落到令牌）、\n      状态矩阵（默认 / 悬停 / 按下 / 禁用 / 焦点）、无障碍要点（键盘可达 + <code>aria-*</code> 语义 + 对比度）、\n      以及<b>与项目现状的真实差距（现状按 Avalonia 仓库如实写，目标按 GPUI 写）</b>。\n      参考来源：<b>B 站网页版</b>（菜单分组、危险二次确认、Toast 位置）、\n      <b>YouTube 桌面版</b>（齿轮菜单、二次 Ctrl/右键的分层菜单、<code>?</code> 快捷键总表）、\n      <b>WAI-ARIA APG</b>（菜单 / 对话框 / Tooltip 的键盘与 ARIA 规范），\n      以及 <b>BewlyCat</b>（本项目的材质基线，浮层一律走 <code>SurfaceElevatedStrong</code>）。</p>\n  </div>\n\n  <!-- ================================================================== -->\n  <!-- 13.0 总览与三条铁律                                                  -->\n  <!-- ================================================================== -->\n  <div class=\"panel\">\n    <h3>13.0 组件总览</h3>\n    <p class=\"note\">下表是本节的索引。<b>GPUI 迁移后，本节的核心从「新建 9 个 <code>Styles/Controls/*.axaml</code>」\n      变成「<b>选用 <code>gpui-component</code> 组件 + 覆盖主题字段</b>」</b>（契约 §1.6 / §6.2）：\n      组件库已经存在 60+ 个组件，项目要做的只有三件事——<b>选哪个模块</b>、<b>覆盖哪些\n      <code>ThemeColor</code> 字段</b>、<b>哪些几何 / 行为必须自建</b>。\n      「现状」列仍按仓库真实代码写（<code>YKPili/Styles/Controls/</code>、<code>YKPili/Styles/Tokens/</code>、\n      <code>YKPili/Views/</code> 是 Avalonia 时代的代码，判断不作废），\n      「目标」列才是迁移后的落点。模块名均取自\n      <code>gpui-component-0.7.3/src/lib.rs</code> 的 <code>pub mod</code>。</p>\n    <table>\n      <thead><tr><th>族</th><th>组件</th><th>核心几何</th><th>现状（仓库真实，Avalonia 口径）</th><th>目标：<code>gpui-component</code> 落点 → 需覆盖的主题字段</th></tr></thead>\n      <tbody>\n        <tr><td>输入</td><td>按钮（accent / ghost / danger / icon / disabled）</td>\n          <td class=\"mono\">sm 28 / md 34 / lg 40</td>\n          <td><span class=\"tag warn\">部分</span> 有胶囊 + accent + large，缺三档高度 / danger / 焦点环</td>\n          <td><code>button::Button</code>（<code>ButtonVariant::{Primary, Ghost, Danger}</code> / <code>ButtonRounded</code>）\n            → 覆盖 <code>primary</code> / <code>danger</code> / <code>ring</code>；\n            三档高度用 <code>Sizable::with_size(Size::Size(px(n)))</code> 或 <code>.h(px(n))</code> 显式给\n            （内置档为 20/24/32，与 28/34/40 不对应）</td></tr>\n        <tr><td>输入</td><td>输入框（普通 / 搜索 / 错误 / 计数 / 禁用）</td>\n          <td class=\"mono\">h 34 / 搜索 h 46</td>\n          <td><span class=\"tag err\">缺失</span> 仓库内 0 处 <code>TextBox</code></td>\n          <td><code>input::{Input, InputState}</code> → 覆盖 <code>foreground</code> /\n            <code>muted_foreground</code>（占位）/ <code>border</code> / <code>ring</code> / <code>danger</code>；\n            圆角走 <code>Theme.radius</code></td></tr>\n        <tr><td>输入</td><td>下拉 / 右键上下文菜单</td>\n          <td class=\"mono\">行高 32 / 最小宽 160</td>\n          <td><span class=\"tag err\">缺失</span> 0 处 <code>ContextMenu</code> / <code>MenuItem</code></td>\n          <td><code>menu::{PopupMenu, ContextMenu}</code>（内部已经 <code>deferred()</code>）\n            → 覆盖 <code>popover</code> / <code>border</code> / <code>foreground</code>；\n            行高与最小宽需自建</td></tr>\n        <tr><td>浮层</td><td>对话框（确认 / 危险确认 / 加载中）</td>\n          <td class=\"mono\">宽 360 / 480</td>\n          <td><span class=\"tag err\">缺失</span> 只有登录页静态玻璃卡片</td>\n          <td><code>dialog::{Dialog, DialogButtonProps}</code> +\n            <code>WindowExt::{open_dialog, open_alert_dialog}</code>\n            → 覆盖 <code>popover</code> / <code>overlay</code> / <code>radius_lg</code></td></tr>\n        <tr><td>浮层</td><td>Toast / 通知条</td>\n          <td class=\"mono\">宽 360 / 右下 / 最多 3 条</td>\n          <td><span class=\"tag err\">缺失</span></td>\n          <td><code>notification::{Notification, NotificationSettings}</code> +\n            <code>WindowExt::push_notification</code> →\n            覆盖 <code>NotificationSettings.{placement, width, max_items, margins}</code>，\n            色走 <code>popover</code> / <code>border</code> / 状态色</td></tr>\n        <tr><td>浮层</td><td>Tooltip</td>\n          <td class=\"mono\">延迟 500ms / 最大宽 240</td>\n          <td><span class=\"tag err\">缺失</span></td>\n          <td><code>tooltip::Tooltip</code>（<code>show_delay</code>）\n            → 覆盖 <code>popover</code> / <code>border</code> / <code>foreground</code></td></tr>\n        <tr><td>表单</td><td>开关 / 滑块 / 复选 / 单选</td>\n          <td class=\"mono\">44×24 / 轨道 4 / 16×16</td>\n          <td><span class=\"tag err\">缺失</span> 仅 <code>SwitchBg</code> 令牌存在，无控件消费</td>\n          <td><code>switch::Switch</code> / <code>slider::Slider</code> /\n            <code>checkbox::Checkbox</code> / <code>radio::{Radio, RadioGroup}</code>\n            → 覆盖 <code>primary</code>（开态 / 选中）/ <code>switch</code>（关态轨道）/\n            <code>switch_thumb</code>（滑块）/ <code>border</code> / <code>ring</code></td></tr>\n        <tr><td>导航</td><td>滚动条</td>\n          <td class=\"mono\">宽 6</td>\n          <td><span class=\"tag ok\">已有</span> 宽度与胶囊滑块已落地，颜色仍是硬编码</td>\n          <td><code>scroll</code> 模块（<code>Scrollable</code> + <code>Theme.scrollbar_mode</code> +\n            <code>ThemeColor.scrollbar</code>）→ 覆盖 <code>scrollbar</code> 色；\n            <b>宽度 6 / 最小 24 可配（base <code>ScrollbarStyles</code>，E-4）</b></td></tr>\n        <tr><td>导航</td><td>分页 / 加载更多 / 无限滚动</td>\n          <td class=\"mono\">—</td>\n          <td><span class=\"tag warn\">部分</span> 有滚动加载逻辑，无「加载更多」与分页 UI</td>\n          <td><code>pagination::Pagination</code> + <code>list::List</code> +\n            <code>v_virtual_list</code> → 覆盖 <code>foreground</code> / <code>primary</code> /\n            <code>muted_foreground</code></td></tr>\n        <tr><td>标识</td><td>徽标 / 标签 / 头像 / 进度条</td>\n          <td class=\"mono\">pill h 22 / badge h 18 / 头像 18·34·46</td>\n          <td><span class=\"tag err\">缺失</span> 仅文档预览有样式，XAML 侧无</td>\n          <td><code>badge::Badge</code> / <code>tag::{Tag, TagVariant}</code> /\n            <code>avatar::Avatar</code> / <code>progress::{Progress, ProgressCircle}</code>\n            → 覆盖 <code>primary</code> / <code>danger</code> / <code>foreground</code>；\n            pill 22 / badge 18 这类几何需自建</td></tr>\n        <tr><td>标识</td><td>骨架 / 空态</td>\n          <td class=\"mono\">复刻真实单元格几何</td>\n          <td><span class=\"tag err\">缺失</span> 第 11 节已把骨架 / 空 / 错误 / 离线四态列为缺口</td>\n          <td><code>skeleton::Skeleton</code> /\n            <code>empty::{Empty, EmptyHeader, EmptyMedia, EmptyTitle, EmptyDescription, EmptyContent}</code>\n            → 覆盖 <code>skeleton</code> / <code>muted_foreground</code> / <code>foreground</code></td></tr>\n        <tr><td>标识</td><td>图标（45 个既有 id + 建议新增）</td>\n          <td class=\"mono\">16 / 20 / 24 / 32</td>\n          <td><span class=\"tag warn\">部分</span> sprite 只存在于文档，XAML 侧无 SVG 渲染管线\n            （GPUI 原生支持 SVG，这条差距随迁移消失）</td>\n          <td><code>svg()</code> + <code>Icon</code>（<code>Icon::path</code> / <code>Icon::data</code> /\n            <code>icon_named!</code>）→ <b>不需要覆盖主题字段</b>，\n            颜色用 <code>.text_color(...)</code> 指定</td></tr>\n      </tbody>\n    </table>\n    <p class=\"note\" style=\"margin-top:var(--space-3)\">一句话记住这张表：<b>「落地文件」这一列已经不存在了</b>——\n      本节不产出任何 <code>.axaml</code>，也不再新建样式文件；产出的是一张\n      <b>「组件 → 模块 → 要覆盖的主题字段 → 要自建的部分」</b>的映射（13.12）。</p>\n\n    <div class=\"grid-2\" style=\"margin-top:16px\">\n      <div class=\"callout err\"><svg class=\"icon icon-sm ti\"><use href=\"#i-alert\"></use></svg>\n        <div><b>铁律一 · 浮在内容上的一切，走 Strong 变体。</b>\n          <b>GPUI 没有元素级 backdrop blur</b>（契约 §1.4）：只有窗口级材质\n          <code>WindowBackgroundAppearance::{Transparent, Blurred, Mica, MicaAlt}</code>，\n          而浮层背后是内容、不是窗口背景，窗口级模糊帮不上忙。\n          因此四层叠加<b>必须保留</b>：① 半透明底 ② 1px 亮边 ③ inset 白色高光 ④ 外阴影，\n          菜单、对话框、Toast、下拉建议这四类浮层的表面一律用 <code>--surface-elevated-strong</code>（0.92），\n          阴影走 <code>--shadow-glass-elevated</code> / <code>--shadow-glass-modal</code>。\n          不用 <code>--surface-elevated</code>（0.68）——背后是封面图时会直接透出花纹。\n          <br><b>GPUI 写法</b>：<code>.yk_surface_elevated_strong()</code> +\n          <code>.border_1().border_color(theme.yk.border_popover)</code> +\n          <code>.shadow(vec![BoxShadow::new(..).inset(), BoxShadow::new(..).blur_radius(px(20.))])</code>\n          （<code>BoxShadow</code> 支持 <code>blur_radius</code> / <code>spread_radius</code> /\n          <code>inset</code>，见 <code>gpui-pre-0.3.9/src/style.rs:349</code>）。\n          <br><b>先后关系不再是层号</b>（契约 §4.3）：\n          菜单 = 所在场景内 <code>deferred()</code>（<code>menu::PopupMenu</code> /\n          <code>menu::ContextMenu</code> 内部已是 <code>deferred()</code>）；\n          模态 = Root 的 dialog 层（<code>WindowExt::open_dialog</code> / <code>open_alert_dialog</code>）；\n          Toast = Root 的 notification 层，且<b>绘制在 dialog 之后</b>\n          （<code>root.rs</code> 的 <code>WindowStateLayers</code> 顺序：sheet → dialog → notification）。\n          于是「遮罩盖住菜单」「Toast 在一切之上」这两条<b>由挂载顺序自动成立</b>，不必再维护数值。\n          <br><b>配套硬性规则（原样保留）：任何模态 / 播放浮窗打开时，关闭所有浮层</b>\n          （菜单、下拉、Popover、Tooltip 一律收起）。</div></div>\n      <div class=\"callout warn\"><svg class=\"icon icon-sm ti\"><use href=\"#i-alert\"></use></svg>\n        <div><b>铁律二 · 尺寸只走语义别名，不写裸数字。</b>\n          本节出现的一切非既有令牌值（菜单行高 32、对话框宽 360、Toast 宽 360 等）\n          都在文件末尾 <b>NOTES「令牌增补」</b>里以「名 / 类型 / 值 / 用途 / 落地文件」报备，\n          由 Lead 统一写进 <code>app/crates/yk-ui/src/theme/dimensions.rs</code>\n          （类型按 Rust 口径：<code>f32</code> / <code>u32</code> / <code>Pixels</code> / <code>Edges&lt;Pixels&gt;</code>），\n          视图里不散落魔法数字。</div></div>\n      <div class=\"callout info\"><svg class=\"icon icon-sm ti\"><use href=\"#i-alert\"></use></svg>\n        <div><b>铁律三 · 状态用主题字段接管，不在视图里硬编码。</b>\n          <b>这条是 Avalonia 时代的债，迁移到 GPUI 时整体消失</b>：\n          <code>gpui-component</code> 的组件全部读 <code>ThemeColor</code>（<code>cx.theme()</code>），\n          项目只需覆盖主题字段，<b>不再有那 56 处字面量</b>，也不需要 <code>DynamicResource</code> 同名覆盖那一套。\n          <br><b>记录（债已清除，留痕备查）</b>：迁移前 <code>FluentOverrides.axaml</code> 里有\n          <b>56 个非透明 <code>SolidColorBrush</code></b> 全是硬编码 hex，靠资源键逐状态覆盖；\n          其中按钮前景 4 态可映射到 <code>Text*</code>、<code>ButtonBackground</code> 三态等于\n          <code>Fill1/2/3</code>，而 <code>ButtonBackgroundDisabled</code> 与\n          <code>AccentButtonForegroundDisabled</code> 在令牌层没有对应值。迁移后这两项的归宿是\n          <b>项目扩展字段</b>（<code>YkSurfaces</code>）或由 <code>ButtonVariant</code> 的 disabled 计算派生，\n          不再需要独立的资源键。本节因此<b>不再给「应覆盖的键清单」</b>，改为给\n          <b>「应覆盖的主题字段」</b>（见 13.12）。</div></div>\n      <div class=\"callout ok\"><svg class=\"icon icon-sm ti\"><use href=\"#i-check\"></use></svg>\n        <div><b>铁律四 · 信息不靠颜色单独传达。</b>\n          危险项、错误态、直播角标都必须同时带<b>图标或文字</b>；\n          颜色只是第二通道。这条与第 10 节「无障碍」清单直接对应。</div></div>\n    </div>\n  </div>\n\n  <!-- ================================================================== -->\n  <!-- 13.1 按钮                                                            -->\n  <!-- ================================================================== -->\n  <div class=\"panel\">\n    <h3>13.1 按钮</h3>\n    <p class=\"note\">参考 <b>B 站网页版</b>（胶囊主按钮 + 文本按钮并置）与\n      <b>BewlyCat</b>（<code>bew-control-height: 34px</code>、<code>bew-control-radius: var(bew-radius-full)</code>）。\n      B 站网页版的主按钮是<b>直角</b>，YKPili 沿用 BewlyCat 的胶囊形——这是<b>刻意不照抄</b>：\n      桌面端密度更高，胶囊形在小尺寸下更易点。\n      GPUI 落地为 <code>button::Button</code> 的\n      <code>ButtonRounded::Size(cx.theme().radius_full())</code>（胶囊半径由主题给，\n      不再需要 XAML 里 <code>RadiusFull</code> 的覆盖），改动成本同样为零。</p>\n\n    <div class=\"grid-2\">\n      <div>\n        <h3 style=\"font-size:var(--fs-control)\">尺寸档</h3>\n        <table>\n          <thead><tr><th>档</th><th>高</th><th>左右内边距</th><th>字号</th><th>图标</th><th>典型位置</th></tr></thead>\n          <tbody>\n            <tr><td>sm</td><td class=\"mono\">28</td><td class=\"mono\">12</td><td class=\"mono\">12 caption</td>\n              <td class=\"mono\">16 icon-sm</td><td>封面悬停操作、菜单内联按钮、标签页内操作</td></tr>\n            <tr><td>md</td><td class=\"mono\">34</td><td class=\"mono\">16</td><td class=\"mono\">13 control</td>\n              <td class=\"mono\">20 icon-md</td><td><b>默认档</b>：工具条、设置面板、播放浮窗按钮</td></tr>\n            <tr><td>lg</td><td class=\"mono\">40</td><td class=\"mono\">20</td><td class=\"mono\">15 body</td>\n              <td class=\"mono\">24 icon-lg</td><td>对话框主操作、登录页</td></tr>\n            <tr><td>顶栏</td><td class=\"mono\">46</td><td class=\"mono\">16</td><td class=\"mono\">15 body</td>\n              <td class=\"mono\">20 icon-md</td><td>搜索框（<code>--topbar-control-h</code>）</td></tr>\n          </tbody>\n        </table>\n        <p class=\"note\"><b>md = 34 就是 <code>--control-h</code></b>，不做第二套基准。\n          sm = 34 − 6、lg = 34 + 6，等差 6 使三档在视觉上可辨识又不至于断档。\n          sm 档 28 与主文档封面悬停按钮的既有 28px 一致；lg 档 40 与原\n          <code>ButtonStyles.axaml</code> 里 <code>Button.large</code> 隐式撑出的高度一致。\n          <br><b>GPUI 注意</b>：<code>gpui-component</code> 的 <code>Size</code> 内置档对应\n          20 / 24 / 32 / 32（<code>button.rs</code> 的 <code>Size::{XSmall, Small, Medium, Large}</code>），\n          <b>与 28 / 34 / 40 不对应</b>，三档必须用\n          <code>with_size(Size::Size(px(28.)))</code> 这类显式像素，\n          不要用 <code>small()</code> / <code>large()</code> 凑近似值。</p>\n      </div>\n      <div>\n        <h3 style=\"font-size:var(--fs-control)\">状态矩阵</h3>\n        <table>\n          <thead><tr><th>变体</th><th>默认</th><th>悬停</th><th>按下</th><th>禁用</th></tr></thead>\n          <tbody>\n            <tr><td>accent</td><td class=\"mono\">theme-primary / text-on-accent</td>\n              <td class=\"mono\">theme-80</td><td class=\"mono\">theme-70</td>\n              <td class=\"mono\">theme-30 / text-4</td></tr>\n            <tr><td>ghost</td><td class=\"mono\">fill-2 / text-1</td>\n              <td class=\"mono\">fill-3</td><td class=\"mono\">fill-4</td>\n              <td class=\"mono\">fill-1 / text-4</td></tr>\n            <tr><td>danger</td><td class=\"mono\">status-error / text-on-accent</td>\n              <td class=\"mono\">brightness(1.08)</td><td class=\"mono\">scale .97</td>\n              <td class=\"mono\">fill-1 / text-4</td></tr>\n            <tr><td>icon</td><td class=\"mono\">透明 / text-2</td>\n              <td class=\"mono\">fill-2 / text-1</td><td class=\"mono\">scale .94</td>\n              <td class=\"mono\">text-4</td></tr>\n          </tbody>\n        </table>\n        <p class=\"note\">按压反馈统一 <code>scale(0.97)</code> + <code>--ease-emphasized</code>，\n          <b>只过渡 transform</b>（契约 §1.3 禁 <code>transition: all</code>）。\n          缩放不参与布局，网格与工具条不会因此抖动。</p>\n      </div>\n    </div>\n\n    <div class=\"s13-demo\" style=\"margin-top:16px\">\n      <div class=\"s13-row s13-tight\">\n        <button class=\"s13-btn s13-accent s13-md s13-focus\"><svg class=\"icon icon-sm\"><use href=\"#i-download\"></use></svg>下载</button>\n        <button class=\"s13-btn s13-ghost s13-md s13-focus\">加入稍后再看</button>\n        <button class=\"s13-btn s13-danger s13-md s13-focus\"><svg class=\"icon icon-sm\"><use href=\"#i-trash\"></use></svg>删除</button>\n        <button class=\"s13-btn s13-accent s13-md s13-disabled\" aria-disabled=\"true\">不可用</button>\n        <button class=\"s13-btn s13-ghost s13-md s13-disabled\" aria-disabled=\"true\">不可用</button>\n      </div>\n      <div class=\"s13-row s13-tight\" style=\"margin-top:var(--space-3)\">\n        <button class=\"s13-btn s13-accent s13-sm\">小</button>\n        <button class=\"s13-btn s13-ghost s13-sm\">小</button>\n        <button class=\"s13-btn s13-accent s13-md\">中</button>\n        <button class=\"s13-btn s13-ghost s13-md\">中</button>\n        <button class=\"s13-btn s13-accent s13-lg\">大</button>\n        <button class=\"s13-btn s13-ghost s13-lg\">大</button>\n      </div>\n      <div class=\"s13-row s13-tight\" style=\"margin-top:var(--space-3)\">\n        <button class=\"s13-iconbtn s13-sm s13-focus\" title=\"收藏\" aria-label=\"收藏\"><svg class=\"icon icon-sm\"><use href=\"#i-bookmark\"></use></svg></button>\n        <button class=\"s13-iconbtn s13-md s13-focus\" title=\"设置\" aria-label=\"设置\"><svg class=\"icon\"><use href=\"#i-settings\"></use></svg></button>\n        <button class=\"s13-iconbtn s13-lg s13-focus\" title=\"更多\" aria-label=\"更多\"><svg class=\"icon icon-lg\"><use href=\"#i-more\"></use></svg></button>\n        <button class=\"s13-iconbtn s13-md s13-disabled\" aria-disabled=\"true\" aria-label=\"不可用\"><svg class=\"icon\"><use href=\"#i-more\"></use></svg></button>\n        <span class=\"s13-label\">图标按钮热区 = 该档高度；顶栏另用 38（见下方差距表）</span>\n      </div>\n    </div>\n\n    <div class=\"grid-2\" style=\"margin-top:16px\">\n      <div class=\"callout info\"><svg class=\"icon icon-sm ti\"><use href=\"#i-alert\"></use></svg>\n        <div><b>无障碍要点。</b>① 焦点环统一 <code>0 0 0 3px var(--theme-30)</code> +\n          <code>inset 0 0 0 1px var(--theme-60)</code>，两套主题下都可见\n          （<b>与第 09 节的统一口径一致</b>，本节不另立焦点环写法）。\n          GPUI 写法是<b>两段 <code>BoxShadow</code></b>：外段\n          <code>BoxShadow::new(px(0.), px(0.), theme_30).spread_radius(px(3.))</code>、\n          内段 <code>BoxShadow::new(px(0.), px(0.), theme_60).spread_radius(px(1.)).inset()</code>；\n          <b><code>gpui-component</code> 的组件自带焦点环</b>\n          （<code>Theme.focus_ring</code> 开关 + <code>ThemeColor.ring</code>，按钮另有自己的\n          <code>FocusLine</code>），只有自建元素才需要手写这两段。\n          ② 图标按钮<b>必须有</b> <code>aria-label</code>（「收藏」而不是「按钮」），\n          GPUI 侧用 <code>Button::accessibility_label(...)</code>。\n          ③ 禁用态用 <code>aria-disabled=\"true\"</code> + 视觉降级，\n          而不是移除元素——保持 Tab 序列里的位置，键盘用户不会「找不到按钮」。\n          ④ 目标尺寸 ≥ 24×24（WCAG 2.2 Target Size Minimum），主操作 ≥ 34（<code>--control-h</code>）。</div></div>\n      <div class=\"callout err\"><svg class=\"icon icon-sm ti\"><use href=\"#i-alert\"></use></svg>\n        <div><b>现状（Avalonia 债）与迁移后的目标。</b>\n          <br>① <b>没有三档高度</b>：现有只有全局 <code>Button</code>（无固定高，高度由\n          <code>Padding 16,8</code> + 字号隐式撑出，约 36–38）与 <code>Button.large</code>\n          （<code>Padding 20,10</code>，约 40）。<code>--control-h 34</code> 这个令牌<b>当前没有任何控件消费</b>。\n          <b>目标</b>：<code>button::Button</code> + <code>Size::Size(px(28./34./40.))</code>，三档一次给足。\n          <br>② <b>没有 danger 变体</b>：Fluent 的资源键只有 <code>Button*</code> 与 <code>AccentButton*</code>，\n          没有错误色底。<b>目标</b>：<code>ButtonVariant::Danger</code> 已内置，\n          颜色读 <code>ThemeColor.danger</code>，项目只覆盖该字段。\n          <br>③ <b>没有焦点环</b>：全项目 <code>grep</code> 不到 <code>focus-visible</code> 或\n          <code>FocusAdorner</code> 样式。<b>目标</b>：组件自带\n          （<code>Theme.focus_ring</code> + <code>FocusLine</code>），自建元素用上面那两段 <code>BoxShadow</code>。\n          <br>④ <b>56 处硬编码色值</b>：<code>FluentOverrides.axaml</code> 里 56 个非透明\n          <code>SolidColorBrush</code> 全是字面量。<b>这笔债随迁移整体消失</b>——\n          <code>ButtonVariant</code> 的四态（normal / hover / active / disabled）由主题计算，\n          项目只覆盖 <code>primary</code> / <code>danger</code> / <code>foreground</code> / <code>ring</code>。\n          <br>⑤ 原 <code>AccentButtonForegroundDisabled</code>（半透明白）与\n          <code>ButtonBackgroundDisabled</code> 在令牌层没有对应值——\n          迁移后它们由 disabled 计算派生；若要独立取值，只能作为\n          <b>项目扩展字段</b>（<code>YkSurfaces</code>）补，<b>不要</b>去改组件库的\n          <code>ThemeColor</code> 语义。<b>该字段在 <code>gpui-component</code> 里没有独立对应项</b>：\n          disabled 由组件从 variant 色（<code>button_*</code> / <code>muted_foreground</code>）\n          叠加透明度派生，要精确复刻就用 <code>YkSurfaces</code> 或 <code>.opacity()</code>，\n          不新增主题字段。</div></div>\n    </div>\n  </div>\n\n  <!-- ================================================================== -->\n  <!-- 13.2 输入框                                                          -->\n  <!-- ================================================================== -->\n  <div class=\"panel\">\n    <h3>13.2 输入框</h3>\n    <p class=\"note\">参考 <b>B 站网页版搜索框</b>（居中胶囊 + 独立「搜索」按钮，提交与输入分离）\n      与 <b>YouTube 桌面版</b>（输入框右侧无按钮，回车即搜索；下拉建议面板跟随输入框宽度）。\n      取舍：YKPili 沿用 B 站的<b>显式提交按钮</b>，因为桌面端搜索是主动动作而非即时过滤；\n      但建议面板的宽度<b>对齐输入框</b>（不是全屏宽），取自 YouTube。</p>\n\n    <div class=\"grid-2\">\n      <div>\n        <h3 style=\"font-size:var(--fs-control)\">几何规格</h3>\n        <table>\n          <thead><tr><th>形态</th><th>高</th><th>圆角</th><th>底 / 描边</th><th>内边距</th><th>备注</th></tr></thead>\n          <tbody>\n            <tr><td>普通输入</td><td class=\"mono\">34（--control-h）</td><td class=\"mono\">8（--radius-md）</td>\n              <td class=\"mono\">fill-1 / border-strong</td><td class=\"mono\">0 12</td>\n              <td>单行；多行时取消固定高、只保留 min-height</td></tr>\n            <tr><td>搜索输入</td><td class=\"mono\">46（--topbar-control-h）</td><td class=\"mono\">9999（--radius-full）</td>\n              <td class=\"mono\">surface-elevated / border-popover</td><td class=\"mono\">0 16</td>\n              <td>复用顶栏胶囊形态，左内 icon-md + 右内清除按钮</td></tr>\n            <tr><td>错误态</td><td class=\"mono\">同宿主</td><td class=\"mono\">同宿主</td>\n              <td class=\"mono\">描边 status-error</td><td class=\"mono\">同宿主</td>\n              <td>下方错误行 caption 12 + i-alert</td></tr>\n            <tr><td>字数统计</td><td class=\"mono\">—</td><td class=\"mono\">—</td>\n              <td class=\"mono\">text-4（超限转 status-error）</td><td class=\"mono\">—</td>\n              <td>右对齐独立行，<b>不占用输入区</b></td></tr>\n            <tr><td>禁用态</td><td class=\"mono\">34</td><td class=\"mono\">8</td>\n              <td class=\"mono\">fill-1 / border-subtle / text-4</td><td class=\"mono\">0 12</td>\n              <td>无焦点环、<code>cursor: not-allowed</code></td></tr>\n          </tbody>\n        </table>\n      </div>\n      <div>\n        <h3 style=\"font-size:var(--fs-control)\">状态矩阵</h3>\n        <table>\n          <thead><tr><th>状态</th><th>边框</th><th>外环</th><th>前景</th></tr></thead>\n          <tbody>\n            <tr><td>默认</td><td class=\"mono\">border-strong</td><td class=\"mono\">无</td><td class=\"mono\">text-1</td></tr>\n            <tr><td>悬停</td><td class=\"mono\">border-strong</td><td class=\"mono\">无</td><td class=\"mono\">text-1</td></tr>\n            <tr><td>聚焦</td><td class=\"mono\">theme-60</td>\n              <td class=\"mono\">0 0 0 3px theme-30（+ 1px theme-60 描边充当内圈）；GPUI = 两段 <code>BoxShadow</code>（外 3px spread + inset 1px）</td>\n              <td class=\"mono\">text-1</td></tr>\n            <tr><td>错误</td><td class=\"mono\">status-error</td><td class=\"mono\">同聚焦</td><td class=\"mono\">text-1</td></tr>\n            <tr><td>占位符</td><td class=\"mono\">—</td><td class=\"mono\">—</td><td class=\"mono\">text-4</td></tr>\n            <tr><td>禁用</td><td class=\"mono\">border-subtle</td><td class=\"mono\">无</td><td class=\"mono\">text-4</td></tr>\n          </tbody>\n        </table>\n        <p class=\"note\">错误态<b>不靠红色边框单独传达</b>：必须同时出现错误文案行与 <code>i-alert</code>，\n          否则色觉障碍用户无法知道哪里出错。</p>\n      </div>\n    </div>\n\n    <div class=\"s13-demo\" style=\"margin-top:16px\">\n      <div class=\"s13-grid2\">\n        <label class=\"s13-field\">\n          <span class=\"s13-label\">普通输入</span>\n          <input class=\"s13-input\" placeholder=\"视频标题 / UP 主昵称\">\n        </label>\n        <label class=\"s13-field\">\n          <span class=\"s13-label\">搜索输入（顶栏胶囊形态）</span>\n          <span class=\"s13-input-row\">\n            <svg class=\"icon icon-sm\" style=\"color:var(--text-4)\"><use href=\"#i-search\"></use></svg>\n            <input class=\"s13-input s13-search\" placeholder=\"搜索视频、UP 主、番剧\">\n          </span>\n        </label>\n        <label class=\"s13-field\">\n          <span class=\"s13-label\">校验错误态</span>\n          <input class=\"s13-input\" aria-invalid=\"true\" value=\"bilibili.com\">\n          <span class=\"s13-error-msg\"><svg class=\"icon icon-sm\"><use href=\"#i-alert\"></use></svg>链接需以 https:// 开头</span>\n        </label>\n        <label class=\"s13-field\">\n          <span class=\"s13-label\">字数统计（超限）</span>\n          <input class=\"s13-input\" value=\"自定义倍速播放记忆\">\n          <span class=\"s13-count s13-over\">32 / 30</span>\n        </label>\n        <label class=\"s13-field\">\n          <span class=\"s13-label\">禁用态</span>\n          <input class=\"s13-input s13-disabled\" value=\"未登录时不可用\" disabled=\"\">\n        </label>\n      </div>\n    </div>\n\n    <div class=\"grid-2\" style=\"margin-top:16px\">\n      <div class=\"callout info\"><svg class=\"icon icon-sm ti\"><use href=\"#i-alert\"></use></svg>\n        <div><b>无障碍要点。</b>① 输入框必须有可见 <code>&lt;label&gt;</code> 或\n          <code>aria-label</code>；占位符<b>不能</b>当标签用（聚焦后消失）。\n          ② 错误时设 <code>aria-invalid=\"true\"</code>，并用 <code>aria-describedby</code>\n          指向错误文案节点的 id，读屏才会连错误一起念出来。\n          ③ 清除按钮要有 <code>aria-label=\"清除\"</code>；\n          ④ 字符计数用 <code>aria-live=\"polite\"</code>，避免每次按键都打断读屏。</div></div>\n      <div class=\"callout err\"><svg class=\"icon icon-sm ti\"><use href=\"#i-alert\"></use></svg>\n        <div><b>现状（Avalonia 债）与迁移后的目标。</b>\n          <b>仓库内 0 处 <code>TextBox</code> 控件</b>——<code>YKPili/Views/</code> 四个视图里\n          没有任何输入控件，<code>Styles/Controls/</code> 也没有 <code>InputStyles.axaml</code>。\n          这意味着：① 输入框的圆角 / 高度 / 聚焦环 / 禁用态<b>全部无定义</b>；\n          ② <code>--control-h 34</code> 与 <code>--topbar-control-h 46</code> 两个令牌\n          目前<b>只被 Fluent 的 Button 隐式接近</b>，没有任何输入框在用；\n          ③ 第 11 节规划中的<b>搜索建议面板（防抖 250ms）</b>需要一个\n          <code>--popover-radius 16</code> 的浮层容器，本节的搜索输入形态就是它的宿主几何。\n          <br><b>目标（GPUI）</b>：不用自建控件，<b>选 <code>input::{Input, InputState}</code></b>，\n          需要覆盖的主题字段是\n          <code>foreground</code>（文字）/ <code>muted_foreground</code>（占位）/\n          <code>border</code>（常态描边）/ <code>ring</code>（聚焦环）/ <code>danger</code>（错误描边）；\n          高度 34 / 46 用 <code>with_size(Size::Size(px(34.)))</code>，圆角 8 走 <code>Theme.radius</code>。\n          <b>需要自建的部分</b>：① 下方错误文案行（caption 12 + <code>i-alert</code>）与\n          字数统计行——<code>Input</code> 本身不画这两行；\n          ② 「错误文案 + 输入框」的 <code>aria-describedby</code> 关联，\n          GPUI 侧的无障碍桥接字段<b>暂缓（第 10 节，E-9）</b>。</div></div>\n    </div>\n  </div>\n\n  <!-- ================================================================== -->\n  <!-- 13.3 下拉菜单 / 右键上下文菜单                                        -->\n  <!-- ================================================================== -->\n  <div class=\"panel\">\n    <h3>13.3 下拉菜单 / 右键上下文菜单</h3>\n    <p class=\"note\">参考 <b>B 站网页版</b>（视频卡片「更多」菜单：分组 + 分隔线 + 危险项「举报」置底，\n      悬停整行高亮，无勾选框）与 <b>YouTube 桌面版</b>（<b>二次 Ctrl/右键</b> 会先弹应用内菜单、\n      再弹系统菜单——见 <a href=\"https://macmost.com/youtube-playback-tips-and-keyboard-shortcuts.html\">MacMost 的\n      YouTube 快捷键说明</a>）。\n      取舍：YKPili <b>只做一层菜单</b>，不做 YouTube 的「应用菜单 + 系统菜单」叠加——\n      桌面客户端没有浏览器宿主菜单，叠加只会让人多点一次；\n      但<b>保留系统的 Shift+F10 / 菜单键唤出</b>，这是键盘用户的唯一入口。</p>\n\n    <div class=\"grid-2\">\n      <div>\n        <h3 style=\"font-size:var(--fs-control)\">几何规格</h3>\n        <table>\n          <thead><tr><th>项</th><th>值</th><th>令牌 / 新令牌</th></tr></thead>\n          <tbody>\n            <tr><td>容器最小宽</td><td class=\"mono\">160</td><td class=\"mono\">新：MenuMinWidth</td></tr>\n            <tr><td>容器最大高</td><td class=\"mono\">320</td><td class=\"mono\">新：MenuMaxHeight（超出滚动）</td></tr>\n            <tr><td>绘制顺序</td><td class=\"mono\">所在场景内 <code>deferred()</code></td>\n              <td class=\"mono\"><code>menu::PopupMenu</code> / <code>menu::ContextMenu</code> 内部已 <code>deferred()</code>；\n                <b>不再有层号</b>（契约 §4.3）</td></tr>\n            <tr><td>容器圆角</td><td class=\"mono\">16</td><td class=\"mono\">--popover-radius</td></tr>\n            <tr><td>容器表面</td><td class=\"mono\">surface-elevated-strong</td><td class=\"mono\">--surface-elevated-strong</td></tr>\n            <tr><td>容器描边 / 阴影</td><td class=\"mono\">border-popover / shadow-glass-elevated</td><td class=\"mono\">既有</td></tr>\n            <tr><td>项行高</td><td class=\"mono\">32</td><td class=\"mono\">新：MenuItemHeight</td></tr>\n            <tr><td>项左右内边距</td><td class=\"mono\">12</td><td class=\"mono\">--space-3</td></tr>\n            <tr><td>图标槽</td><td class=\"mono\">16（icon-sm），槽宽 20</td><td class=\"mono\">--icon-sm / --icon-md</td></tr>\n            <tr><td>分隔线</td><td class=\"mono\">1px，margin 上下 4</td><td class=\"mono\">--border-subtle / --space-1</td></tr>\n            <tr><td>容器上下内边距</td><td class=\"mono\">4</td><td class=\"mono\">--space-1</td></tr>\n          </tbody>\n        </table>\n      </div>\n      <div>\n        <h3 style=\"font-size:var(--fs-control)\">项形态矩阵</h3>\n        <table>\n          <thead><tr><th>形态</th><th>前景</th><th>悬停底</th><th>图标</th><th>可聚焦</th></tr></thead>\n          <tbody>\n            <tr><td>普通项</td><td class=\"mono\">text-1</td><td class=\"mono\">fill-2</td><td class=\"mono\">text-3 / icon-sm</td>\n              <td>是</td></tr>\n            <tr><td>图标项</td><td class=\"mono\">text-1</td><td class=\"mono\">fill-2</td>\n              <td class=\"mono\">text-3 / icon-sm</td><td>是</td></tr>\n            <tr><td>危险项</td><td class=\"mono\">status-error</td><td class=\"mono\">fill-2</td>\n              <td class=\"mono\">status-error / icon-sm</td><td>是</td></tr>\n            <tr><td>禁用项</td><td class=\"mono\">text-4</td><td class=\"mono\">无（hover 不变）</td>\n              <td class=\"mono\">text-4</td><td><b>是</b>（可聚焦不可激活）</td></tr>\n            <tr><td>分隔线</td><td class=\"mono\">—</td><td class=\"mono\">—</td><td class=\"mono\">—</td>\n              <td><b>否</b></td></tr>\n            <tr><td>带快捷键尾标</td><td class=\"mono\">text-1</td><td class=\"mono\">fill-2</td>\n              <td class=\"mono\">—</td><td>是</td></tr>\n          </tbody>\n        </table>\n        <p class=\"note\">「禁用项仍可聚焦」是 APG 的硬性要求：\n          键盘用户要能读到「这里有个功能但现在不能用」，而不是让焦点直接跳过它。</p>\n      </div>\n    </div>\n\n    <div class=\"s13-demo\" style=\"margin-top:16px\">\n      <div class=\"s13-row s13-tight\" style=\"align-items:flex-start\">\n        <div>\n          <div class=\"s13-label\" style=\"margin-bottom:var(--space-2)\">下拉菜单（按钮触发）</div>\n          <div class=\"s13-menu-anchor\">\n            <button class=\"s13-iconbtn s13-md s13-focus\" aria-haspopup=\"menu\" aria-expanded=\"true\" aria-label=\"更多操作\">\n              <svg class=\"icon\"><use href=\"#i-more\"></use></svg></button>\n            <div class=\"s13-menu\" role=\"menu\" aria-label=\"视频操作\">\n              <div class=\"s13-menu-item\" role=\"menuitem\" tabindex=\"-1\">\n                <svg class=\"icon icon-sm s13-menu-icon\"><use href=\"#i-clock\"></use></svg>稍后再看</div>\n              <div class=\"s13-menu-item\" role=\"menuitem\" tabindex=\"-1\">\n                <svg class=\"icon icon-sm s13-menu-icon\"><use href=\"#i-bookmark\"></use></svg>收藏到文件夹\n                <span class=\"s13-menu-tail\">…</span></div>\n              <div class=\"s13-menu-item\" role=\"menuitem\" tabindex=\"-1\">\n                <svg class=\"icon icon-sm s13-menu-icon\"><use href=\"#i-share\"></use></svg>分享</div>\n              <div class=\"s13-menu-sep\" role=\"separator\"></div>\n              <div class=\"s13-menu-item s13-danger\" role=\"menuitem\" tabindex=\"-1\">\n                <svg class=\"icon icon-sm s13-menu-icon\"><use href=\"#i-ban\"></use></svg>不感兴趣</div>\n              <div class=\"s13-menu-item\" role=\"menuitem\" tabindex=\"-1\" aria-disabled=\"true\">\n                <svg class=\"icon icon-sm s13-menu-icon\"><use href=\"#i-download\"></use></svg>下载（未登录）</div>\n            </div>\n          </div>\n        </div>\n        <div>\n          <div class=\"s13-label\" style=\"margin-bottom:var(--space-2)\">右键上下文菜单（同结构，锚点跟随光标）</div>\n          <div class=\"s13-menu\" role=\"menu\" aria-label=\"上下文操作\">\n            <div class=\"s13-menu-item\" role=\"menuitem\" tabindex=\"-1\">\n              <svg class=\"icon icon-sm s13-menu-icon\"><use href=\"#i-copy\"></use></svg>复制链接</div>\n            <div class=\"s13-menu-item\" role=\"menuitem\" tabindex=\"-1\">\n              <svg class=\"icon icon-sm s13-menu-icon\"><use href=\"#i-play-o\"></use></svg>在此处播放</div>\n            <div class=\"s13-menu-sep\" role=\"separator\"></div>\n            <div class=\"s13-menu-item s13-danger\" role=\"menuitem\" tabindex=\"-1\">\n              <svg class=\"icon icon-sm s13-menu-icon\"><use href=\"#i-ban\"></use></svg>举报</div>\n          </div>\n        </div>\n      </div>\n      <p class=\"s13-note\" style=\"margin:var(--space-3) 0 0\">\n        尾标 <code>…</code> 是 APG 的约定：<b>该菜单项会打开一个对话框</b>（本例「收藏到文件夹」）。\n        有全局快捷键的项在右侧同位置显示键位文案，<b>文案由第 14 节统一分配</b>，本节只定形态。</p>\n    </div>\n\n    <div class=\"grid-2\" style=\"margin-top:16px\">\n      <div class=\"callout info\"><svg class=\"icon icon-sm ti\"><use href=\"#i-alert\"></use></svg>\n        <div><b>键盘导航（依 <a href=\"https://www.w3.org/WAI/ARIA/apg/patterns/menubar/\">WAI-ARIA APG 菜单模式</a>）。</b>\n          <br>触发按钮上：<code>Enter</code> / <code>Space</code> / <code>↓</code> 打开并落在<b>第一项</b>，\n          <code>↑</code> 打开并落在<b>最后一项</b>。\n          <br>菜单打开后：<code>↑</code>/<code>↓</code> 逐项移动（末尾回到首项），\n          <code>Home</code>/<code>End</code> 跳首尾，<code>Enter</code> 激活并关闭，\n          <code>Esc</code> 关闭并<b>把焦点还给触发按钮</b>，\n          <code>Tab</code> 直接移出菜单（同时关闭）。\n          <br>可选：输入可打印字符跳到下一个以该字符开头的项（B 站网页版无此行为，\n          但 APG 建议加，桌面端收益大）。\n          <br><b>贴边翻转</b>：容器靠近视口右缘时左对齐靠右、靠下缘时向上弹；\n          翻转后仍保持与触发元素的 4px（<code>--space-1</code>）间距。\n          <br><b>触发方式</b>：① 按钮点击（<code>menu::PopupMenu</code>）② 右键（<code>menu::ContextMenu</code>，\n          锚点由光标给）③ <code>Shift+F10</code> / <code>菜单键</code>（键盘唤出，右键菜单必须有此路径；\n          GPUI 侧的键位绑定方式<b>暂缓（第 10 节，E-7）</b>）。\n          <br><b>实现现状（E-8，已核实 2026-10-25）</b>：<code>tooltip</code> / <code>select</code> /\n          <code>combobox</code> 走 <code>gpui_base::Positioner::side</code>，空间不足会<b>自动翻到对侧</b>；\n          <code>Popover</code> 的 <code>anchor()</code>（corner 路径，按钮下拉菜单也走它）和\n          <code>ContextMenu</code> / 子菜单（gpui <code>anchored()</code> + <code>snap_to_window_with_margin</code>）\n          <b>只贴边夹住、不翻转</b>，菜单必须按 13.3.1 自建定位。\n          <br><b>以上是组件级键盘模型；全局键位总表（各键的全局绑定）由第 14 节统一收口</b>，\n          本节不另立一份全局键位清单。菜单项尾标的快捷键文案同样由第 14 节分配，\n          本节只规定「有快捷键的项在右侧留出尾标槽位」这一组件形态。</div></div>\n      <div class=\"callout err\"><svg class=\"icon icon-sm ti\"><use href=\"#i-alert\"></use></svg>\n        <div><b>现状（Avalonia 债）与迁移后的目标。</b>\n          <b>仓库内 0 处 <code>ContextMenu</code> / <code>MenuItem</code> / <code>MenuFlyout</code></b>——\n          卡片「更多」按钮（第 04 节的第 4 层悬停操作）目前<b>没有对应实现</b>，\n          <code>VideoPlayerView.axaml</code> 里的按钮也全是无菜单的裸按钮。\n          <br>· 原 <code>Border.glass.elevated</code> 在 <code>GlassSurface.axaml</code> 里用的是\n          <code>--surface-elevated</code>（0.68），菜单必须叠加 <code>.on-content</code> 切到 Strong 变体。\n          <b>目标</b>：菜单表面读 <code>ThemeColor.popover</code>，项目把这个字段配成\n          Strong 变体（0.92）即可，<b>不再有「两套玻璃类要记得叠加」这个坑</b>。\n          <br>· <b>层号已取消</b>：菜单不需要 <code>LayerMenu 65</code>，也不需要写进\n          <code>app/crates/yk-ui/src/theme/dimensions.rs</code>——它靠\n          <code>menu::PopupMenu</code> / <code>ContextMenu</code> 内部的 <code>deferred()</code> 绘制；\n          模态打开时由「关闭所有浮层」这条红线强制收起菜单，\n          而不是靠「菜单层号低于遮罩」这种几何关系。</div></div>\n    </div>\n\n    <h3 id=\"e8-flip\" style=\"margin-top:20px\">13.3.1 贴边翻转（E-8 结论与落地方案）</h3>\n    <div class=\"callout info\">\n      <svg class=\"icon icon-sm ti\"><use href=\"#i-check\"></use></svg>\n      <div><b>核实结论：库只自动处理了一部分。</b>结论来自 <code>gpui-component</code> 0.8.0、\n        <code>gpui-base</code> 0.8.0 与 <code>vendor/gpui-pre</code> 源码（2026-10-25）。\n        <table style=\"margin-top:8px\">\n          <thead><tr><th>组件</th><th>定位路径</th><th>贴边行为</th></tr></thead>\n          <tbody>\n            <tr><td>Tooltip</td><td class=\"mono\">Positioner::side</td>\n              <td><b>自动翻</b>：首选边放不下就换对侧，再夹进视口</td></tr>\n            <tr><td>Select / Combobox / DatePicker</td><td class=\"mono\">Positioner::side</td>\n              <td><b>自动翻</b>：同上，<code>offset</code> 间距在翻转后保留</td></tr>\n            <tr><td>Popover / 按钮下拉菜单</td><td class=\"mono\">Popover → Positioner::corner</td>\n              <td><b>不翻</b>：只 clamp；源码注释为 “Legacy anchoring clamps without flipping”</td></tr>\n            <tr><td>ContextMenu / 子菜单</td><td class=\"mono\">gpui anchored() + snap_to_window_with_margin</td>\n              <td><b>不翻</b>：贴边夹住，会盖住触发元素</td></tr>\n          </tbody>\n        </table>\n        <b>结论</b>：tooltip 与下拉类可直接用；popover / 菜单若要满足本文档\n        「右缘右对齐、下缘向上弹、保持 4px」，必须由项目侧定位。\n      </div>\n    </div>\n\n    <div class=\"panel\" style=\"margin-top:12px\">\n      <h3 style=\"font-size:var(--fs-control)\">落地方案：yk-ui 统一实现一次</h3>\n      <p class=\"note\" style=\"margin:0 0 8px\">不要在业务代码里直接用\n        <code>Popover::anchor()</code> 或 <code>ContextMenu</code> 的默认锚点：前者是 corner\n        路径只 clamp；后者的 <code>anchor</code> 字段私有、内部固定\n        <code>snap_to_window_with_margin</code>，配置不出翻转。</p>\n      <p class=\"note\" style=\"margin:0 0 8px\"><b>① 用 <code>Positioner::side</code> 承载浮层</b>。\n        它按实际测量出的浮层尺寸决定翻不翻，不需要提前知道菜单宽高；\n        <code>offset</code> 表示触发元素到浮层的间距，翻到对侧后仍然是 4px。</p>\n<pre style=\"margin:8px 0;padding:10px 12px;background:var(--fill-1);border:1px solid var(--border-subtle);border-radius:var(--radius-sm);overflow-x:auto;font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:12px;line-height:1.6;color:var(--text-2)\">// app/crates/yk-ui/src/overlay.rs\nuse gpui::{deferred, prelude::*, px, Bounds};\nuse gpui::base::{Align, Placement, Positioner, POPUP_PRIORITY};\n\n/// 所有菜单/气泡共用的锚定浮层：贴边自动翻转 + 4px 间距 + 8px 视口边距。\npub fn anchored_surface(\n    trigger_bounds: Bounds&lt;Pixels&gt;,\n    surface: impl IntoElement + 'static,\n) -&gt; impl IntoElement {\n    deferred(\n        Positioner::side(trigger_bounds)\n            .placement(Placement::Bottom) // 首选向下，放不下自动翻上\n            .align(Align::Start)          // 默认与触发元素左对齐\n            .offset(px(4.))               // 4px 间距，翻转后依然生效\n            .margin(px(8.))               // 视口安全边距\n            .occlude()                    // 浮层区域拦截鼠标\n            .child(surface),\n    )\n    .with_priority(POPUP_PRIORITY)\n}</pre>\n      <p class=\"note\" style=\"margin:8px 0 0\"><b>② 触发 bounds 从哪来</b>：按钮触发在\n        <code>on_prepaint</code> 里记录 <code>Bounds&lt;Pixels&gt;</code>；右键菜单用\n        <code>Bounds::new(cursor_position, size(px(0.), px(0.)))</code>，把光标点当成零尺寸触发区。</p>\n      <p class=\"note\" style=\"margin:8px 0 0\"><b>③ 右缘严格右对齐（可选）</b>：\n        <code>Positioner</code> 只翻「边」不翻「对齐」，宽度不够时由 <code>clamp</code>\n        保证不出界，但菜单可能不贴触发元素右缘。要严格右对齐就分两帧：首帧\n        <code>Align::Start</code>，在 <code>on_position</code> 里记下实际宽度，\n        若 <code>trigger.right() + 4 + width &gt; viewport.width - 8</code>，下一帧切\n        <code>Align::End</code>。只要求「不出界」时，<code>clamp</code> 已经够用。</p>\n      <p class=\"note\" style=\"margin:8px 0 0\"><b>④ 子菜单</b>：<code>PopupMenu</code> 内部的二级菜单\n        固定走 <code>snap_to_window_with_margin</code>，不会左右翻；需要严格翻转时按 NOTES\n        第 14 条自建子菜单或 patch 组件。</p>\n      <p class=\"note\" style=\"margin:8px 0 0\"><b>验收</b>：1280×820 窗口，触发点分别贴右下角、\n        左上角；菜单完整可见、与触发元素间距 4px、翻到上方时不盖住触发元素。\n        <code>Positioner</code> 无动画，<code>reduce_motion</code> 不影响。</p>\n    </div>\n  </div>\n\n  <!-- ================================================================== -->\n  <!-- 13.4 对话框                                                          -->\n  <!-- ================================================================== -->\n  <div class=\"panel\">\n    <h3>13.4 对话框</h3>\n    <p class=\"note\">参考 <b>B 站网页版的危险二次确认</b>（删除收藏夹时弹出「确定要删除吗？」，\n      按钮右对齐、主操作用蓝、危险操作用红）与 <b>YouTube 桌面版</b>（对话框关闭后焦点回到触发按钮）。\n      取舍：YKPili 的对话框<b>不做「居中大遮罩 + 卡片」以外的形态</b>，\n      不做 YouTube 那种右侧抽屉式设置面板——设置项数量可控，用对话框够。</p>\n\n    <div class=\"grid-2\">\n      <div>\n        <h3 style=\"font-size:var(--fs-control)\">几何与层级</h3>\n        <table>\n          <thead><tr><th>项</th><th>值</th><th>令牌 / 新令牌</th></tr></thead>\n          <tbody>\n            <tr><td>挂载</td><td class=\"mono\">Root 的 dialog 层</td>\n              <td class=\"mono\"><code>WindowExt::open_dialog</code> / <code>open_alert_dialog</code>；\n                <b>独立层，不是场景内浮层</b>（契约 §4.3）</td></tr>\n            <tr><td>与菜单的关系</td><td class=\"mono\">菜单先收起</td>\n              <td class=\"mono\">菜单是场景内 <code>deferred()</code>；模态打开前由红线强制关闭，不靠数值比较</td></tr>\n            <tr><td>与 Toast 的关系</td><td class=\"mono\">Toast 后绘制</td>\n              <td class=\"mono\">Root 层顺序 sheet → dialog → notification，Toast 天然在上（<code>root.rs</code>）</td></tr>\n            <tr><td>遮罩</td><td class=\"mono\">scrim</td><td class=\"mono\">--scrim</td></tr>\n            <tr><td>对话框表面</td><td class=\"mono\">surface-elevated-strong</td><td class=\"mono\">既有</td></tr>\n            <tr><td>圆角</td><td class=\"mono\">24</td><td class=\"mono\">--modal-radius</td></tr>\n            <tr><td>阴影</td><td class=\"mono\">shadow-glass-modal</td><td class=\"mono\">既有</td></tr>\n            <tr><td>宽（确认类）</td><td class=\"mono\">360</td><td class=\"mono\">新：DialogWidthSm</td></tr>\n            <tr><td>宽（内容 / 表单类）</td><td class=\"mono\">480</td><td class=\"mono\">新：DialogWidthMd</td></tr>\n            <tr><td>内边距</td><td class=\"mono\">24</td><td class=\"mono\">--space-6</td></tr>\n            <tr><td>标题 / 正文字号</td><td class=\"mono\">15 semibold / 15 regular</td>\n              <td class=\"mono\">--fs-title / --fs-body</td></tr>\n            <tr><td>按钮区</td><td class=\"mono\">右对齐，间距 8</td><td class=\"mono\">--space-2</td></tr>\n          </tbody>\n        </table>\n      </div>\n      <div>\n        <h3 style=\"font-size:var(--fs-control)\">行为矩阵</h3>\n        <table>\n          <thead><tr><th>行为</th><th>确认对话框</th><th>危险确认对话框</th><th>加载中</th></tr></thead>\n          <tbody>\n            <tr><td>初始焦点</td><td>主按钮</td><td><b>取消按钮</b>（最不破坏性的选项）</td><td>对话框标题（<code>tabindex=\"-1\"</code>）</td></tr>\n            <tr><td>Esc</td><td>关闭 = 取消</td><td>关闭 = 取消（<b>允许</b>，符合 APG 字面要求）</td><td>不关闭</td></tr>\n            <tr><td>点遮罩</td><td>关闭 = 取消</td><td>关闭 = 取消</td><td>不关闭</td></tr>\n            <tr><td>Tab 循环</td><td>框内循环</td><td>框内循环</td><td>框内循环</td></tr>\n            <tr><td>关闭后焦点</td><td colspan=\"2\">归还<b>触发元素</b>；触发元素已消失则归还到逻辑上的上一个可聚焦元素</td>\n              <td>—</td></tr>\n            <tr><td>主按钮</td><td class=\"mono\">accent</td><td class=\"mono\">danger，<b>文案自解释</b>（如「永久删除该收藏夹」），<b>不预设焦点</b></td>\n              <td class=\"mono\">禁用 + 转圈</td></tr>\n            <tr><td>副按钮</td><td class=\"mono\">ghost「取消」</td><td class=\"mono\">ghost「取消」</td>\n              <td class=\"mono\">禁用</td></tr>\n          </tbody>\n        </table>\n        <p class=\"note\">加载中<b>不自动关闭</b>对话框：请求完成后由业务代码显式关闭，\n          否则用户会在成功提示出现前就失去上下文。</p>\n      </div>\n    </div>\n\n    <div class=\"s13-demo\" style=\"margin-top:16px\">\n      <div class=\"s13-grid2\">\n        <div class=\"s13-dialog-stage\">\n          <div class=\"s13-scrim\"></div>\n          <div class=\"s13-dialog\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"s13-dlg-a\">\n            <div class=\"s13-dialog-head\">\n              <h4 class=\"s13-dialog-title\" id=\"s13-dlg-a\">清除播放记录？</h4>\n            </div>\n            <div class=\"s13-dialog-body\">\n              清除后无法恢复，本地缓存的 46 条观看记录会被一并删除。\n            </div>\n            <div class=\"s13-dialog-foot\">\n              <button class=\"s13-btn s13-ghost s13-md\">取消</button>\n              <button class=\"s13-btn s13-accent s13-md\">确定</button>\n            </div>\n          </div>\n        </div>\n        <div class=\"s13-dialog-stage\">\n          <div class=\"s13-scrim\"></div>\n          <div class=\"s13-dialog\" role=\"alertdialog\" aria-modal=\"true\" aria-labelledby=\"s13-dlg-b\">\n            <div class=\"s13-dialog-head\" style=\"display:flex;gap:var(--space-3);align-items:flex-start\">\n              <svg class=\"icon icon-lg s13-dialog-icon\"><use href=\"#i-alert\"></use></svg>\n              <div>\n                <h4 class=\"s13-dialog-title\" id=\"s13-dlg-b\">删除收藏夹「稍后再看」？</h4>\n                <p class=\"s13-note\" style=\"margin:0\">该文件夹下的 12 个视频将被移除，此操作不可撤销。</p>\n              </div>\n            </div>\n            <div class=\"s13-dialog-foot\">\n              <button class=\"s13-btn s13-ghost s13-md\" autofocus=\"\">取消</button>\n              <button class=\"s13-btn s13-danger s13-md\"><svg class=\"icon icon-sm\"><use href=\"#i-trash\"></use></svg>永久删除该收藏夹</button>\n            </div>\n          </div>\n        </div>\n      </div>\n    </div>\n\n    <div class=\"grid-2\" style=\"margin-top:16px\">\n      <div class=\"callout info\"><svg class=\"icon icon-sm ti\"><use href=\"#i-alert\"></use></svg>\n        <div><b>无障碍要点（依 <a href=\"https://www.w3.org/WAI/ARIA/apg/patterns/dialog-modal/\">APG 对话框模式</a>）。</b>\n          ① 容器 <code>role=\"dialog\"</code> + <code>aria-modal=\"true\"</code> +\n          <code>aria-labelledby</code> 指向标题；危险确认用 <code>role=\"alertdialog\"</code>。\n          ② Tab / Shift+Tab <b>在框内循环</b>，不得移出。\n          ③ 框内必须有一个<b>可见的关闭控件</b>（关闭图标或取消按钮）。\n          ④ <code>aria-modal</code> 只有在「背景真的不可交互 + 背景真的被遮住」时才可加——\n          两者缺一，读屏用户会被骗。\n          ⑤ 关闭后焦点归还触发元素。\n          ⑥ <b>危险确认的两条硬规则</b>（防止误删，而不是靠「关不掉」）：\n          <b>(a)</b> 初始焦点落在<b>取消</b>上；<b>(b)</b> 主操作文案必须<b>自解释</b>\n          ——写「永久删除该收藏夹」而不是「确定」，且主操作<b>不预设焦点</b>。\n          Esc 仍允许关闭（关闭 = 取消，符合 APG 字面要求）。\n          ⑦ <b>组件级键盘模型</b>如上；全局键位总表由第 14 节统一收口，本节不另立全局键位清单。</div></div>\n      <div class=\"callout err\"><svg class=\"icon icon-sm ti\"><use href=\"#i-alert\"></use></svg>\n        <div><b>现状（Avalonia 债）与迁移后的目标。</b>\n          <b>项目没有任何对话框组件。</b><code>LoginView.axaml</code> 的登录卡片是一张\n          <code>Border Classes=\"glass modal\" Width=\"380\" Padding=\"32,36\"</code> 的静态卡片——\n          它<b>没有遮罩、没有焦点陷阱、没有 Esc 处理、没有关闭按钮</b>，\n          而且宽 380 / 内边距 32,36 是<b>写死的字面量</b>，没有走令牌。\n          <br>· 原 <code>--modal-radius 24</code> 与 <code>--shadow-glass-modal</code> 已在令牌层就位，\n          <code>Border.glass.modal</code> 也已定义好，<b>只差一个带遮罩的对话框宿主控件</b>。\n          <br>· 原 <code>--scrim</code> 令牌（<code>OverlayScrim</code>）已存在但没有视图消费它。\n          <b>目标</b>：遮罩不用项目自己画——<code>dialog::Dialog</code> 自带\n          <code>overlay</code> / <code>overlay_closable</code> / <code>keyboard</code> / <code>entrance</code>，\n          颜色读 <code>ThemeColor.overlay</code>；宽 360 / 480 用\n          <code>Dialog::w(px(360.))</code> / <code>(px(480.))</code>；圆角走 <code>Theme.radius_lg</code>；\n          危险确认走 <code>window.open_alert_dialog</code> + <code>DialogButtonProps</code>\n          （<code>ok_variant(ButtonVariant::Danger)</code>）。\n          <b>需要自建的部分</b>：危险确认的「初始焦点落在取消」——<code>gpui-component</code> 是否支持\n          指定初始焦点<b>暂缓（第 10 节，E-6）</b>；恢复时若不支持，则在 <code>Dialog</code> 打开后手动 <code>focus</code> 取消按钮。</div></div>\n    </div>\n  </div>\n\n  <!-- ================================================================== -->\n  <!-- 13.5 Toast / 通知条                                                  -->\n  <!-- ================================================================== -->\n  <div class=\"panel\">\n    <h3>13.5 Toast / 通知条</h3>\n    <p class=\"note\">参考 <b>B 站网页版</b>（操作成功提示出现在<b>页面顶部居中</b>，\n      例如「已添加至稍后再看」）与 <b>YouTube 桌面版</b>（订阅成功提示在<b>右下角</b>）。\n      取舍：桌面客户端窗口宽、且可能同时开着播放器浮窗，<b>右下角</b>比顶部居中更不打扰；\n      同时因为 <b>GPUI 没有元素级 backdrop blur</b>，右下角的 Toast 会压在<b>封面网格</b>上，\n          必须用 Strong 变体（<code>ThemeColor.popover</code> 配成 0.92），否则半透明底会让封面花纹透上来。\n      <br><b>层级取舍（不再用层号）</b>：Toast 由 Root 的 notification 层绘制，\n          <b>在 sheet / dialog 之后</b>（<code>root.rs</code> 的 <code>WindowStateLayers</code> 顺序），\n          所以「操作成功」的反馈天然盖过模态——操作反馈的可见性优先于模态的独占性。\n          菜单是场景内 <code>deferred()</code>，模态打开时由红线强制关闭，而不是靠数值排在遮罩之下。</p>\n\n    <div class=\"grid-2\">\n      <div>\n        <h3 style=\"font-size:var(--fs-control)\">几何与层级</h3>\n        <table>\n          <thead><tr><th>项</th><th>值</th><th>令牌 / 新令牌</th></tr></thead>\n          <tbody>\n            <tr><td>位置</td><td class=\"mono\">右下，距窗口边 24</td>\n              <td class=\"mono\"><code>NotificationSettings.placement = Anchor::BottomRight</code>；\n                <code>margins = Edges::all(px(24.))</code></td></tr>\n            <tr><td>绘制顺序</td><td class=\"mono\">Root 的 notification 层（最后绘制）</td>\n              <td class=\"mono\">不需要层号：由 <code>WindowStateLayers</code> 的挂载顺序决定</td></tr>\n            <tr><td>宽度</td><td class=\"mono\">360</td><td class=\"mono\"><code>NotificationSettings.width = px(360.)</code></td></tr>\n            <tr><td>圆角</td><td class=\"mono\">8</td><td class=\"mono\">--radius-md</td></tr>\n            <tr><td>内边距</td><td class=\"mono\">10 12</td><td class=\"mono\">新：ToastPadding</td></tr>\n            <tr><td>表面 / 描边 / 阴影</td><td class=\"mono\">surface-elevated-strong / border-popover / shadow-glass-elevated</td>\n              <td class=\"mono\">既有</td></tr>\n            <tr><td>堆叠方向</td><td class=\"mono\">自下而上，最多 3 条</td>\n              <td class=\"mono\"><code>NotificationSettings.max_items = 3</code></td></tr>\n            <tr><td>动效</td><td class=\"mono\">只淡入淡出，200ms / EaseStandard</td>\n              <td class=\"mono\">--dur-normal / --ease-standard；\n                组件的退出时长常量已是 200ms（<code>NOTIFICATION_EXIT_DURATION</code>），\n                进入时长是 400ms 固定常量，暂不单独配置</td></tr>\n          </tbody>\n        </table>\n      </div>\n      <div>\n        <h3 style=\"font-size:var(--fs-control)\">停留时长与语义</h3>\n        <table>\n          <thead><tr><th>类型</th><th>图标</th><th>图标色</th><th>停留</th><th>读屏播报</th></tr></thead>\n          <tbody>\n            <tr><td>成功</td><td class=\"mono\">i-check</td><td class=\"mono\">status-success</td><td class=\"mono\">2000ms</td>\n              <td class=\"mono\">polite</td></tr>\n            <tr><td>信息</td><td class=\"mono\">i-alert</td><td class=\"mono\">status-info</td><td class=\"mono\">3000ms</td>\n              <td class=\"mono\">polite</td></tr>\n            <tr><td>警告</td><td class=\"mono\">i-alert</td><td class=\"mono\">status-warning</td><td class=\"mono\">5000ms</td>\n              <td class=\"mono\">polite</td></tr>\n            <tr><td>错误</td><td class=\"mono\">i-alert</td><td class=\"mono\">status-error</td>\n              <td class=\"mono\">常驻（手动关闭）</td><td class=\"mono\">assertive</td></tr>\n          </tbody>\n        </table>\n        <p class=\"note\"><b>语义靠图标 + 颜色双通道</b>：底色默认走中性\n          <code>--fill-2</code> / <code>--surface-elevated-strong</code>，语义由彩色图标承担\n          （<code>--status-success</code> / <code>--status-warning</code> /\n          <code>--status-error</code> / <code>--status-info</code>）——\n          两套主题下都成立，且不引入新的色值。\n          <br><b>状态底（可选，第二种写法）</b>：主文档已导出\n          <code>--status-success-10</code> / <code>--status-success-20</code> /\n          <code>--status-warning-20</code> / <code>--status-error-20</code> 等半透明档\n          （迁移后对应 <code>palette.rs</code> 里的同义常量），\n          需要更强的语义色块时用「<code>--status-*-20</code> 底 + 同色文字/图标」；\n          <b>无论用哪种底色，图标 + 文案都不能少</b>。\n          <br><b>GPUI 落地</b>：四种语义直接对应\n          <code>Notification::{success, info, warning, error}</code>\n          （图标与颜色由 <code>NotificationType</code> 从 <code>success</code> / <code>info</code> /\n          <code>warning</code> / <code>danger</code> 派生）。\n          <b>停留时长的坑</b>：<code>Notification</code> 只暴露\n          <code>autohide(bool)</code>，自动消失时长在 <code>NotificationList</code> 内部固定为 5s\n          （<code>notification.rs:872</code>），所以设计里的 2000 / 3000 / 5000 三档不能直接配。\n          <b>E-1 已核实：默认 <code>autohide(true)</code> 固定 5s</b>，内部会处理\n          指针悬停 / 键盘焦点暂停与恢复；<b>暂直接用它，不自己计时</b>。\n          只有确实需要 2s / 3s 档时，才在包装层计时后调 <code>dismiss()</code>。\n          「错误常驻」用 <code>autohide(false)</code> 即可。</p>\n      </div>\n    </div>\n\n    <div class=\"s13-demo\" style=\"margin-top:16px;position:relative;min-height:180px\">\n      <div class=\"s13-toast-host\">\n        <div class=\"s13-toast s13-success\" role=\"status\">\n          <svg class=\"icon icon-sm s13-toast-icon\"><use href=\"#i-check\"></use></svg>\n          <span>已添加至「稍后再看」</span>\n        </div>\n        <div class=\"s13-toast s13-info\" role=\"status\">\n          <svg class=\"icon icon-sm s13-toast-icon\"><use href=\"#i-alert\"></use></svg>\n          <span>倍速已记住：下次播放仍为 1.5×</span>\n        </div>\n        <div class=\"s13-toast s13-error\" role=\"alert\">\n          <svg class=\"icon icon-sm s13-toast-icon\"><use href=\"#i-alert\"></use></svg>\n          <span>下载失败：磁盘空间不足</span>\n          <button class=\"s13-toast-close\" aria-label=\"关闭\"><svg class=\"icon icon-sm\"><use href=\"#i-close\"></use></svg></button>\n        </div>\n      </div>\n    </div>\n\n    <div class=\"grid-2\" style=\"margin-top:16px\">\n      <div class=\"panel\" style=\"margin:0\">\n        <h3 style=\"font-size:var(--fs-control)\">通知条（页内条，不浮层）</h3>\n        <div class=\"s13-toast-bar\">\n          <svg class=\"icon icon-sm\" style=\"color:var(--status-info)\"><use href=\"#i-wifi-off\"></use></svg>\n          <span>当前处于离线状态，已为你展示本地缓存的 46 条内容</span>\n        </div>\n        <p class=\"note\">通知条是<b>页内元素</b>（不进浮层场景，不带遮罩），\n          用于「状态变了但不打断操作」——例如离线、缓存已更新。\n          与 Toast 的区别：通知条<b>常驻直到状态恢复</b>，Toast 是<b>瞬时反馈</b>。\n          第 05 节的「离线 / 弱网」状态就是通知条的宿主。</p>\n      </div>\n      <div class=\"callout info\"><svg class=\"icon icon-sm ti\"><use href=\"#i-alert\"></use></svg>\n        <div><b>无障碍要点。</b>\n          ① 成功 / 信息 / 警告用 <code>role=\"status\"</code> + <code>aria-live=\"polite\"</code>；\n          错误用 <code>role=\"alert\"</code> + <code>aria-live=\"assertive\"</code>。\n          ② <b>错误 Toast 不得自动消失</b>——自动消失的 assertive 播报会被读屏截断，\n          用户听不到一半。③ 悬停时<b>暂停消失计时</b>，指针移出后继续计剩余时间；\n          用户正在读或准备点「重试」时不能把提示抽走。\n          ④ 同类型多条合并为「×N」，不重复堆叠。\n          ⑤ 关闭按钮必须有 <code>aria-label</code>。</div></div>\n    </div>\n\n    <div class=\"callout err\" style=\"margin-top:var(--space-3)\"><svg class=\"icon icon-sm ti\"><use href=\"#i-alert\"></use></svg>\n      <div><b>现状（Avalonia 债）与迁移后的目标。</b><b>项目没有任何 Toast / 通知条实现</b>——\n        第 11 节列的「骨架 / 空 / 错误态」全部缺失，错误信息目前只能靠\n        <code>System.Diagnostics.Trace.WriteLine</code>（见 <code>HomeViewModel.cs</code> 的\n        <code>[HomeVM]</code> / <code>[FillData]</code> 日志）输出到控制台，\n        <b>用户在界面上看不到任何失败反馈</b>。这正是 Toast 要补的洞。\n        <br><b>目标</b>：不新建 toast 容器——选\n        <code>notification::Notification</code> + <code>NotificationSettings</code> +\n        <code>WindowExt::push_notification</code>，容器、堆叠、位置、进出场动效都由组件库给。\n        <b>需要自建的部分</b>：① 四档停留时长的计时（见上）；\n        ② 「同类型多条合并为 ×N」的去重策略（<code>Notification::id</code> / <code>id1</code>\n        只做同 id 替换，合并计数需项目侧维护）。</div></div>\n  </div>\n\n  <!-- ================================================================== -->\n  <!-- 13.6 Tooltip                                                         -->\n  <!-- ================================================================== -->\n  <div class=\"panel\">\n    <h3>13.6 Tooltip</h3>\n    <p class=\"note\">参考 <b>WAI-ARIA APG Tooltip 模式</b>（不接收焦点、Esc 关闭、\n      <code>aria-describedby</code> 关联）与 <b>YouTube 桌面版</b>（时间轴悬停显示章节名与预览帧）。\n      取舍：YKPili 的 Tooltip <b>只做纯文字</b>，不做 YouTube 那种带缩略图的大气泡——\n      缩略图气泡本质是「悬浮卡片」，需要独立的定位与层号管理，\n      而 YKPili 已有「点击卡片打开播放浮窗」这条更短的路径。</p>\n\n    <div class=\"grid-2\">\n      <div>\n        <h3 style=\"font-size:var(--fs-control)\">几何与时序</h3>\n        <table>\n          <thead><tr><th>项</th><th>值</th><th>令牌 / 新令牌</th></tr></thead>\n          <tbody>\n            <tr><td>出现延迟（指针）</td><td class=\"mono\">500ms</td>\n              <td class=\"mono\"><code>Tooltip::builder(..).show_delay = Some(Duration::from_millis(500))</code>\n                （字段见 <code>tooltip.rs:204</code>）</td></tr>\n            <tr><td>出现延迟（键盘聚焦）</td><td class=\"mono\">0ms</td><td class=\"mono\">—</td></tr>\n            <tr><td>消失</td><td class=\"mono\">指针移出即消（不延迟）</td><td class=\"mono\">—</td></tr>\n            <tr><td>最大宽</td><td class=\"mono\">240</td><td class=\"mono\">新：TooltipMaxWidth</td></tr>\n            <tr><td>内边距</td><td class=\"mono\">4 8</td><td class=\"mono\">--space-1 / --space-2</td></tr>\n            <tr><td>圆角</td><td class=\"mono\">4</td><td class=\"mono\">--radius-sm</td></tr>\n            <tr><td>字号 / 行高</td><td class=\"mono\">12 / 16</td><td class=\"mono\">--fs-caption / --lh-caption</td></tr>\n            <tr><td>箭头</td><td class=\"mono\">8×8 旋转 45°</td><td class=\"mono\">新：TooltipArrowSize</td></tr>\n            <tr><td>与宿主间距</td><td class=\"mono\">8</td><td class=\"mono\">--space-2</td></tr>\n            <tr><td>位置</td><td class=\"mono\">默认上方居中，空间不足翻转下 / 左 / 右</td><td class=\"mono\">—</td></tr>\n          </tbody>\n        </table>\n      </div>\n      <div>\n        <h3 style=\"font-size:var(--fs-control)\">使用边界</h3>\n        <table>\n          <thead><tr><th>场景</th><th>能用 Tooltip</th><th>不能用 Tooltip（必须换别的）</th></tr></thead>\n          <tbody>\n            <tr><td>图标按钮</td><td>补充说明（如「倍速：记忆上次设置」）</td>\n              <td>按钮的<b>名称</b>——必须写进 <code>aria-label</code></td></tr>\n            <tr><td>截断标题</td><td>完整标题</td><td>—</td></tr>\n            <tr><td>播放进度条</td><td>已看 12:34 / 共 45:00</td>\n              <td>进度百分比——必须同时可见</td></tr>\n            <tr><td>禁用按钮</td><td>禁用原因</td>\n              <td>—（注意：禁用按钮收不到指针事件，需由包裹层承载 Tooltip）</td></tr>\n            <tr><td>关键操作说明</td><td>—</td>\n              <td><b>绝不可用</b>：删除确认、支付、隐私授权等必须常驻可见</td></tr>\n          </tbody>\n        </table>\n      </div>\n    </div>\n\n    <div class=\"s13-demo\" style=\"margin-top:16px\">\n      <div class=\"s13-row s13-tight\" style=\"align-items:flex-end\">\n        <span class=\"s13-tip\">\n          <button class=\"s13-iconbtn s13-md\" aria-label=\"清晰度\"><svg class=\"icon\"><use href=\"#i-settings\"></use></svg></button>\n          <span class=\"s13-tip-body\" role=\"tooltip\" id=\"s13-tip-1\">清晰度 · 1080P 高清</span>\n          <span class=\"s13-tip-arrow\" aria-hidden=\"true\"></span>\n        </span>\n        <span class=\"s13-tip\">\n          <button class=\"s13-iconbtn s13-md\" aria-label=\"倍速\"><svg class=\"icon\"><use href=\"#i-speed\"></use></svg></button>\n          <span class=\"s13-tip-body\" role=\"tooltip\" id=\"s13-tip-2\">倍速 · 会记住上次设置</span>\n          <span class=\"s13-tip-arrow\" aria-hidden=\"true\"></span>\n        </span>\n        <span class=\"s13-tip\">\n          <button class=\"s13-iconbtn s13-md\" aria-label=\"更多\"><svg class=\"icon\"><use href=\"#i-more\"></use></svg></button>\n          <span class=\"s13-tip-body\" role=\"tooltip\" id=\"s13-tip-3\">更多操作</span>\n          <span class=\"s13-tip-arrow\" aria-hidden=\"true\"></span>\n        </span>\n      </div>\n    </div>\n\n    <div class=\"grid-2\" style=\"margin-top:16px\">\n      <div class=\"callout info\"><svg class=\"icon icon-sm ti\"><use href=\"#i-alert\"></use></svg>\n        <div><b>无障碍要点（依 <a href=\"https://www.w3.org/WAI/ARIA/apg/patterns/tooltip/\">APG Tooltip 模式</a>）。</b>\n          ① Tooltip <b>不接收焦点</b>；焦点始终留在触发元素上。\n          ② 容器 <code>role=\"tooltip\"</code>，触发元素用 <code>aria-describedby</code> 指向它。\n          ③ <code>Esc</code> 立即关闭。\n          ④ 指针移入 Tooltip 本身<b>不</b>关闭（若将来要放链接，需改用非模态对话框）。\n          ⑤ 键盘聚焦触发元素时<b>立即</b>显示（不延迟），否则键盘用户拿不到说明。\n          ⑥ Tooltip 内容<b>不能是完成任务所必需的信息</b>。\n          ⑦ 以上为组件级键盘模型；全局键位总表由第 14 节统一收口。</div></div>\n      <div class=\"callout err\"><svg class=\"icon icon-sm ti\"><use href=\"#i-alert\"></use></svg>\n        <div><b>现状（Avalonia 债）与迁移后的目标。</b><b>项目没有任何 Tooltip</b>。\n          当前所有图标按钮靠 <code>title</code> 属性（见主文档预览的 <code>.iconbtn</code> 用法）\n          提供说明，但 Avalonia 桌面端的 <code>title</code> 只会变成原生窗口标题栏提示，\n          <b>不是控件级 Tooltip</b>——既没有延迟控制，也没有 <code>aria-describedby</code> 关联，\n          读屏用户基本拿不到。而第 10 节明确要求「图标按钮必须有 accessibilityLabel」，\n          所以 Tooltip 与 <code>aria-label</code> 是<b>两件事</b>：前者给人看，后者给读屏器念。\n          <br><b>目标</b>：选 <code>tooltip::Tooltip</code>，通过\n          <code>ManagedTooltipExt</code> 直接挂在按钮上（<code>Button</code> 自带 tooltip 入口）；\n          500ms 延迟用 <code>show_delay</code>；表面读 <code>popover</code> / <code>border</code>。\n          <b>E-5 已核实</b>：最大宽可用 <code>.max_w(px(240.))</code> 覆盖，内边距可用\n          <code>px_2().py_0p5()</code> 近似；<b>箭头 8×8 组件未内建</b>，需自绘。\n          键盘聚焦即时显示可用 <code>show_delay(Duration::ZERO)</code>；\n          <code>aria-describedby</code> 没有按 ID 关联的能力，退化为\n          <code>aria_description</code> 文本。\n          <br><b>E-8 已核实</b>：Tooltip 走 <code>Positioner::side</code>，贴边自动翻到对侧，\n          项目侧无需自建定位（结论与菜单方案见 13.3.1）。</div></div>\n    </div>\n  </div>\n\n  <!-- ================================================================== -->\n  <!-- 13.7 开关 / 滑块 / 复选框 / 单选                                      -->\n  <!-- ================================================================== -->\n  <div class=\"panel\">\n    <h3 id=\"e10-switch\">13.7 开关 / 滑块 / 复选框 / 单选</h3>\n    <p class=\"note\">参考 <b>YouTube 桌面版设置页</b>（左标题右开关的两列布局，\n      开关本体约 44×26）与 <b>B 站网页版</b>（复选框为方框 + 主题色勾）。\n      取舍：YKPili 采用 <b>左标签右控件</b>的两列设置行，而不是 B 站的「勾选框在文字右侧」——\n      桌面端设置项多，两列对齐才好纵向扫读。</p>\n\n    <div class=\"grid-2\">\n      <div>\n        <h3 style=\"font-size:var(--fs-control)\">几何规格</h3>\n        <table>\n          <thead><tr><th>控件</th><th>几何</th><th>轨道 / 描边</th><th>滑块 / 标记</th><th>焦点环</th></tr></thead>\n          <tbody>\n            <tr><td>开关</td><td class=\"mono\">44×24</td>\n              <td class=\"mono\">关：ThemeColor.switch；开：ThemeColor.primary</td>\n              <td class=\"mono\">20 圆钮，ThemeColor.switch_thumb</td>\n              <td class=\"mono\">theme-30 外圈 + theme-60 内圈</td></tr>\n            <tr><td>滑块</td><td class=\"mono\">轨道 h 4；thumb ⌀14</td>\n              <td class=\"mono\">未播放：fill-3</td>\n              <td class=\"mono\">已播放：theme-primary</td>\n              <td class=\"mono\">同左（套在 thumb 上）</td></tr>\n            <tr><td>复选框</td><td class=\"mono\">16×16，圆角 4</td>\n              <td class=\"mono\">border-strong 1.5px</td>\n              <td class=\"mono\">选中：theme-primary 底 + i-check 白勾</td>\n              <td class=\"mono\">theme-30 外圈 + theme-60 内圈</td></tr>\n            <tr><td>单选</td><td class=\"mono\">⌀16</td>\n              <td class=\"mono\">border-strong 1.5px</td>\n              <td class=\"mono\">选中：⌀8 实心 theme-primary</td>\n              <td class=\"mono\">theme-30 外圈 + theme-60 内圈</td></tr>\n            <tr><td>禁用态</td><td class=\"mono\">几何不变</td>\n              <td class=\"mono\">fill-2 / border-subtle</td><td class=\"mono\">text-4</td>\n              <td class=\"mono\">无</td></tr>\n          </tbody>\n        </table>\n        <p class=\"note\">新令牌：<code>SWITCH_WIDTH 44</code> / <code>SWITCH_HEIGHT 24</code> /\n          <code>SWITCH_THUMB_SIZE 20</code> / <code>SLIDER_TRACK_HEIGHT 4</code> /\n          <code>SLIDER_THUMB_SIZE 14</code> / <code>CHECKBOX_SIZE 16</code> / <code>RADIO_SIZE 16</code>\n          ——全部落在 <code>app/crates/yk-ui/src/theme/dimensions.rs</code>（<code>f32</code> / <code>Pixels</code>）。\n          组件本身的尺寸若由 <code>gpui-component</code> 内定，就用 <code>.size(px(n))</code> 压在实例上，\n          不改组件库。</p>\n      </div>\n      <div>\n        <h3 style=\"font-size:var(--fs-control)\">标签关联与键盘</h3>\n        <table>\n          <thead><tr><th>控件</th><th>ARIA</th><th>键盘</th><th>标签关联</th></tr></thead>\n          <tbody>\n            <tr><td>开关</td><td class=\"mono\">role=switch / aria-checked</td>\n              <td class=\"mono\">Space 切换</td><td class=\"mono\">左标签 + 控件成对，读屏需连读</td></tr>\n            <tr><td>滑块</td><td class=\"mono\">role=slider / aria-valuenow·min·max</td>\n              <td class=\"mono\">←→ 步进，Shift+←→ 大步，Home/End 两端</td>\n              <td class=\"mono\">aria-label 写明「音量」而非「滑块」</td></tr>\n            <tr><td>复选框</td><td class=\"mono\">role=checkbox / aria-checked</td>\n              <td class=\"mono\">Space 切换</td><td class=\"mono\">点击文字也要能切换</td></tr>\n            <tr><td>单选</td><td class=\"mono\">role=radio / aria-checked；组 role=radiogroup</td>\n              <td class=\"mono\">←→ 组内移动，Space 选中</td><td class=\"mono\">组用 legend 命名</td></tr>\n          </tbody>\n        </table>\n        <p class=\"s13-note\">键盘列为<b>组件级键盘模型</b>；全局键位总表由第 14 节统一收口。</p>\n        <div class=\"callout warn\" style=\"margin-top:12px\"><svg class=\"icon icon-sm ti\"><use href=\"#i-alert\"></use></svg>\n          <div><b>开关 vs 复选框：语义不同，不能互换。</b>\n            开关 = <b>立即生效</b>的设置（开/关弹幕、自动播放），改动立刻生效且可撤销；\n            复选框 = <b>随表单提交</b>的选项（同时勾选多个下载画质）。\n            同一个设置如果先勾选再点「保存」，就该用复选框；\n            勾上就生效就该用开关。B 站网页版常把两者混用，是我们要避开的。</div></div>\n      </div>\n    </div>\n\n    <div class=\"s13-demo\" style=\"margin-top:16px\">\n      <div class=\"s13-col\">\n        <span class=\"s13-labeled\">\n          <button class=\"s13-switch\" role=\"switch\" aria-checked=\"true\" aria-label=\"默认开启弹幕\"></button>\n          默认开启弹幕\n        </span>\n        <span class=\"s13-labeled\">\n          <button class=\"s13-switch\" role=\"switch\" aria-checked=\"false\" aria-label=\"记忆播放倍速\"></button>\n          记忆播放倍速\n        </span>\n        <span class=\"s13-labeled\">\n          <button class=\"s13-switch\" role=\"switch\" aria-checked=\"false\" aria-disabled=\"true\" aria-label=\"自动播放（未登录不可用）\"></button>\n          自动播放（未登录不可用）\n        </span>\n        <div class=\"s13-row s13-tight\" style=\"margin-top:var(--space-2)\">\n          <span class=\"s13-slider\" role=\"slider\" aria-valuenow=\"62\" aria-valuemin=\"0\" aria-valuemax=\"100\" aria-label=\"音量\" tabindex=\"0\">\n            <span class=\"s13-slider-track\"></span>\n            <span class=\"s13-slider-fill\" style=\"width:62%\"></span>\n            <span class=\"s13-slider-thumb\" style=\"left:62%\"></span>\n          </span>\n          <span class=\"s13-label\">音量 62%</span>\n        </div>\n        <div class=\"s13-row s13-tight\" style=\"margin-top:var(--space-2)\">\n          <span class=\"s13-labeled\">\n            <span class=\"s13-check\" role=\"checkbox\" aria-checked=\"true\" tabindex=\"0\" aria-label=\"同时下载字幕\"></span>\n            同时下载字幕\n          </span>\n          <span class=\"s13-labeled\">\n            <span class=\"s13-check\" role=\"checkbox\" aria-checked=\"false\" tabindex=\"0\" aria-label=\"下载高码率\"></span>\n            下载高码率\n          </span>\n          <span class=\"s13-labeled\">\n            <span class=\"s13-radio\" role=\"radio\" aria-checked=\"true\" tabindex=\"0\" aria-label=\"画质 1080P\"><span class=\"s13-radio-dot\"></span></span>\n            1080P\n          </span>\n          <span class=\"s13-labeled\">\n            <span class=\"s13-radio\" role=\"radio\" aria-checked=\"false\" tabindex=\"0\" aria-label=\"画质 4K\"></span>\n            4K\n          </span>\n        </div>\n      </div>\n    </div>\n\n    <div class=\"callout err\" style=\"margin-top:var(--space-3)\"><svg class=\"icon icon-sm ti\"><use href=\"#i-alert\"></use></svg>\n      <div><b>现状（Avalonia 债）与迁移后的目标。</b>\n        <b>仓库内 0 处 <code>ToggleSwitch</code> / <code>Slider</code> / <code>CheckBox</code> / <code>RadioButton</code></b>。\n        <br>· 令牌层<b>已经有</b> <code>SwitchBg</code>（亮暗两套各一个浅灰值，\n        注释与变量名均写作「控件专用」），但<b>没有任何控件消费它</b>——\n        这是一个「先有令牌、后有控件」的孤儿键。<b>迁移后直接废除该孤儿键</b>：\n        关态轨道读 <code>ThemeColor.switch</code>（项目已映射成 <code>fill_3</code>），\n        滑块读 <code>ThemeColor.switch_thumb</code>（映射成白），\n        开态读 <code>ThemeColor.primary</code>。\n        <b>E-10 已核实</b>：<code>Switch</code> 实际读 <code>theme.tokens.switch</code> /\n        <code>tokens.switch_thumb</code>，而 <code>Theme::update</code> 改 <code>colors</code>\n        会经 <code>reconcile</code> 同步到 tokens，所以只改 <code>ThemeColor</code> 即可，\n        <b>不需要 <code>yk.switch_track</code> 扩展字段</b>。API 见\n        <a href=\"https://gpui-kit.com/zh-CN/component/switch/\">Switch 组件文档</a>；\n        该页只列 API 与尺寸，字段名以 0.8.0 源码 <code>switch.rs</code> 为准。\n        <br>· 第 04 节规划的<b>观看进度条</b>（卡片第 3 层）与<b>播放器进度条</b>是同一套滑块几何，\n        但目前 <code>VideoPlayerView.axaml</code> 的进度条是手写的 <code>Border</code> 叠放\n        （第 649–661 行附近），<b>没有使用 <code>Slider</code> 控件</b>，因此不可键盘操作、也没有 ARIA 语义。\n        <b>目标</b>：改用 <code>slider::Slider</code>（键盘步进、<code>valuenow</code> 语义随组件来），\n        卡片进度条若只是「只读细条」，用 <code>progress::Progress</code> 而不是 Slider。\n        <br>· <code>VideoPlayerView.axaml</code> 里另有 <b>19 处硬编码色值</b>（控制栏的半透明白、\n        底部的黑色渐变遮罩、以及<b>一处直接写死的主题色</b>）。\n        其中播放器浮层的白 / 黑半透明值属于契约 §1.1 允许的「播放器浮层例外」，<b>迁移后保留</b>；\n        <b>但那一处写死的主题色随迁移消失</b>——取 <code>cx.theme().primary</code> 即可，\n        主题色若将来可切换也不会脱钩。</div></div>\n  </div>\n\n  <!-- ================================================================== -->\n  <!-- 13.8 滚动条                                                          -->\n  <!-- ================================================================== -->\n  <div class=\"panel\">\n    <h3>13.8 滚动条</h3>\n    <p class=\"note\">参考 <b>BewlyCat</b>（滚动条轨道完全透明，只留一条细滑块）\n      与 <b>主文档预览</b>（<code>.app-scroll::-webkit-scrollbar { width: 6px }</code> +\n      <code>thumb background: var(--fill-4)</code>）。\n      取舍：YKPili 与 BewlyCat 一致采用<b>细条 + 透明轨道</b>，\n      但滑块常态用 <code>--fill-3</code> 而非 <code>--fill-4</code>——\n      主文档预览的 <code>--fill-4</code> 在亮色下太重，与细条的克制感冲突。</p>\n\n    <div class=\"grid-2\">\n      <div>\n        <h3 style=\"font-size:var(--fs-control)\">规格</h3>\n        <table>\n          <thead><tr><th>项</th><th>值</th><th>令牌</th></tr></thead>\n          <tbody>\n            <tr><td>轨道宽</td><td class=\"mono\">6</td><td class=\"mono\">--scroll-bar-size（既有）</td></tr>\n            <tr><td>轨道底</td><td class=\"mono\">透明</td><td class=\"mono\">—</td></tr>\n            <tr><td>滑块常态</td><td class=\"mono\">fill-3</td><td class=\"mono\">--fill-3</td></tr>\n            <tr><td>滑块悬停 / 按下</td><td class=\"mono\">fill-4</td><td class=\"mono\">--fill-4</td></tr>\n            <tr><td>滑块圆角</td><td class=\"mono\">9999</td><td class=\"mono\">--radius-full</td></tr>\n            <tr><td>两端箭头按钮</td><td class=\"mono\">隐藏</td><td class=\"mono\">—</td></tr>\n            <tr><td>最小滑块长度</td><td class=\"mono\">24</td><td class=\"mono\">新：SCROLL_BAR_MIN_THUMB_LENGTH</td></tr>\n          </tbody>\n        </table>\n      </div>\n      <div>\n        <h3 style=\"font-size:var(--fs-control)\">现状核对</h3>\n        <dl class=\"kv\">\n          <dt><code>app/crates/yk-ui/src/theme/dimensions.rs</code></dt>\n          <dd class=\"mono\">SCROLL_BAR_SIZE = 6 ✓（迁移后照样存在）</dd>\n          <dt><code>scroll</code> 模块</dt>\n          <dd>透明轨道 + 胶囊滑块由 <code>Scrollable</code> 与 <code>ScrollbarMode</code> 承担；\n              <b>不再有 <code>RepeatButton</code> 模板</b>（GPUI 没有模板这层抽象）</dd>\n          <dt>滑块配色</dt>\n          <dd>迁移后读 <code>ThemeColor.scrollbar</code>；常态 / 悬停的深浅两档若需要分别取值，\n              落在项目扩展字段（<code>fill_3</code> / <code>fill_4</code>）里</dd>\n          <dt>CSS 侧</dt>\n          <dd>主文档预览有 <code>.app-scroll::-webkit-scrollbar</code>，\n              <b>但它只是设计稿的可视化</b>——GPUI 不使用 CSS</dd>\n        </dl>\n        <div class=\"callout warn\" style=\"margin-top:12px\"><svg class=\"icon icon-sm ti\"><use href=\"#i-alert\"></use></svg>\n          <div><b>现状与迁移后的目标。</b>① 原 Avalonia 侧靠 <code>ScrollBar</code> 的资源键 + 模板样式实现，\n            和 HTML 预览是两套写法；<b>迁移后两套都作废</b>，统一由 <code>scroll</code> 模块出。\n            ② 原 7 处硬编码 hex（<code>ScrollBarPanningThumbBackground</code> 等）随迁移消失，\n            颜色只从 <code>ThemeColor.scrollbar</code> / 项目扩展字段取。\n            ③ <b>可配（E-4）</b>：base primitives 的 <code>ScrollbarStyles</code> 暴露\n            <code>thumb(|t| t.width(px(6.)).min_length(px(24.)))</code>；默认 thumb 6、最小 48，\n            显式设 24 即可。组件级 Scrollable 页只是没写这段。</div></div>\n      </div>\n    </div>\n\n    <div class=\"s13-demo\" style=\"margin-top:16px\">\n      <div class=\"s13-row s13-tight\" style=\"align-items:flex-start\">\n        <div class=\"s13-scrollbox\">\n          <div class=\"s13-col\" style=\"gap:var(--space-2)\">\n            <span class=\"s13-note\">第 1 行 · 虚拟列表按行节流</span>\n            <span class=\"s13-note\">第 2 行</span><span class=\"s13-note\">第 3 行</span>\n            <span class=\"s13-note\">第 4 行</span><span class=\"s13-note\">第 5 行</span>\n            <span class=\"s13-note\">第 6 行</span><span class=\"s13-note\">第 7 行</span>\n            <span class=\"s13-note\">第 8 行</span><span class=\"s13-note\">第 9 行</span>\n          </div>\n        </div>\n        <div class=\"s13-col\" style=\"gap:var(--space-2)\">\n          <span class=\"s13-label\">滚动条几何（6px 轨道 · fill-3 滑块）</span>\n          <span class=\"s13-scrollbar\" style=\"height:120px;display:block;background:var(--fill-1);position:relative\">\n            <span class=\"s13-scrollbar-thumb\" style=\"position:absolute;left:0;top:0;width:6px;height:44px;display:block\"></span>\n          </span>\n          <span class=\"s13-label\">悬停时滑块加深到 fill-4</span>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- ================================================================== -->\n  <!-- 13.9 分页 / 加载更多 / 无限滚动                                      -->\n  <!-- ================================================================== -->\n  <div class=\"panel\">\n    <h3>13.9 分页 / 加载更多 / 无限滚动</h3>\n    <p class=\"note\">参考 <b>B 站网页版</b>（首页推荐流是<b>滚动加载</b>，搜索结果页底部是\n      「加载更多」按钮，分区页用<b>分页器</b>）与 <b>YouTube 桌面版</b>（订阅流滚动加载，\n      搜索结果是分页）。\n      取舍：YKPili 沿用 B 站的划分——<b>浏览型用滚动加载，定位型用分页</b>。</p>\n\n    <div class=\"grid-2\">\n      <div>\n        <h3 style=\"font-size:var(--fs-control)\">何时用哪种</h3>\n        <table>\n          <thead><tr><th>场景</th><th>方案</th><th>理由</th><th>与现有实现的关系</th></tr></thead>\n          <tbody>\n            <tr><td>首页推荐流</td><td><b>无限滚动</b></td>\n              <td>浏览型，目标是「一直刷」</td>\n              <td>已实现：<code>EvaluateLoadMore()</code></td></tr>\n            <tr><td>搜索结果</td><td><b>加载更多按钮</b></td>\n              <td>结果集有限且需要可复现的位置</td><td>待建</td></tr>\n            <tr><td>收藏夹 / 历史</td><td><b>分页</b></td>\n              <td>需要跳到某一页、按时间定位</td><td>待建</td></tr>\n            <tr><td>消息中心</td><td><b>游标</b>（接口原生 cursor）</td>\n              <td>有未读锚点、要稳定定位：<code>msgfeed</code> 给 <code>cursor.id + reply_time</code>，\n                私信给 <code>begin_ts</code>（微秒）与 <code>seqno</code></td><td>待建</td></tr>\n            <tr><td>番剧 / 影视详情页剧集表</td><td><b>不分页</b>，全部列出</td>\n              <td>条目少</td><td>—</td></tr>\n          </tbody>\n        </table>\n      </div>\n      <div>\n        <h3 style=\"font-size:var(--fs-control)\">几何规格</h3>\n        <table>\n          <thead><tr><th>项</th><th>值</th><th>令牌 / 新令牌</th></tr></thead>\n          <tbody>\n            <tr><td>分页按钮</td><td class=\"mono\">28×28，圆角 8</td><td class=\"mono\">--radius-md</td></tr>\n            <tr><td>分页间距</td><td class=\"mono\">4</td><td class=\"mono\">--space-1</td></tr>\n            <tr><td>当前页</td><td class=\"mono\">theme-primary 底 / text-on-accent</td><td class=\"mono\">既有</td></tr>\n            <tr><td>翻页箭头</td><td class=\"mono\">i-chevron-left / i-chevron-right</td><td class=\"mono\">既有</td></tr>\n            <tr><td>「加载更多」按钮</td><td class=\"mono\">通栏 × 34，1px 虚线 border-strong</td>\n              <td class=\"mono\">--control-h / --border-strong</td></tr>\n            <tr><td>加载中占位</td><td class=\"mono\">一行骨架，单元格 208×184</td>\n              <td class=\"mono\">--cover-cell-w / --cover-cell-h</td></tr>\n            <tr><td>到底提示</td><td class=\"mono\">caption 12 / text-4</td><td class=\"mono\">--fs-caption</td></tr>\n          </tbody>\n        </table>\n      </div>\n    </div>\n\n    <div class=\"s13-demo\" style=\"margin-top:16px\">\n      <div class=\"s13-col\">\n        <div class=\"s13-row s13-tight\">\n          <span class=\"s13-label\">分页器</span>\n          <span class=\"s13-pager\" role=\"navigation\" aria-label=\"分页\">\n            <button class=\"s13-page\" aria-label=\"上一页\"><svg class=\"icon icon-sm\"><use href=\"#i-chevron-left\"></use></svg></button>\n            <button class=\"s13-page\">1</button>\n            <button class=\"s13-page\" aria-current=\"page\">2</button>\n            <button class=\"s13-page\">3</button>\n            <button class=\"s13-page\">…</button>\n            <button class=\"s13-page\">12</button>\n            <button class=\"s13-page\" aria-label=\"下一页\"><svg class=\"icon icon-sm\"><use href=\"#i-chevron-right\"></use></svg></button>\n          </span>\n        </div>\n        <button class=\"s13-loadmore\"><svg class=\"icon icon-sm\"><use href=\"#i-refresh\"></use></svg>加载更多</button>\n        <div class=\"s13-endnote\">\n          <svg class=\"icon icon-sm\"><use href=\"#i-inbox\"></use></svg>已经到底了 · 共 200 条\n        </div>\n      </div>\n    </div>\n\n    <div class=\"grid-2\" style=\"margin-top:16px\">\n      <div class=\"callout info\"><svg class=\"icon icon-sm ti\"><use href=\"#i-alert\"></use></svg>\n        <div><b>与首页虚拟列表的关系（三条硬约束）。</b>\n          ① <b>追加数据不得重建容器池</b>：<code>AppendRecommendVideos</code> 里走\n          <code>FillContainerData()</code> 重映射，<b>不是</b> <code>RecalculateOnResize</code> 的重建分支\n          ——两者混用会导致滚动位置错乱（第 08 节已写明的红线）。\n          <br>② <b>加载更多不能改变视口高度</b>：追加的内容只影响 <code>Canvas</code> 的总高，\n          <code>FirstVisibleRowIndex</code> 不变，因此用户不会「被弹下去」。\n          <br>③ <b>底部骨架必须复刻真实单元格几何</b>（208×184），\n          否则加载完成瞬间网格会跳——这与第 05 节骨架屏的要求同源。</div></div>\n      <div class=\"callout err\"><svg class=\"icon icon-sm ti\"><use href=\"#i-alert\"></use></svg>\n        <div><b>与项目现状的差距。</b>\n          <code>HomeViewModel</code> 已有的加载更多逻辑<b>是完整可用的</b>：\n          <code>EvaluateLoadMore()</code> 在「滚到底 / 内容不足一屏 / 滚动进度 ≥ 90%」三种情况下触发\n          <code>LoadMoreRequested</code>，<code>UpdateOnScroll()</code> 返回是否跨行以便 View 跳过重排，\n          <code>_isLoadingMore</code> 防并发。\n          <br><b>缺口有四：</b>\n          <br>① <b>没有「加载中」的可视反馈</b>——<code>_isLoadingMore</code> 只是内部布尔，\n          界面上看不到任何指示。\n          <br>② <b>没有「加载更多」按钮形态</b>——搜索结果等需要显式按钮的场景无法复用。\n          <br>③ <b>硬上限 200 条没有出口</b>：<code>MaxItemCount = 200</code> 到顶后\n          <code>EvaluateLoadMore()</code> 直接 return，用户不知道「已经到底了」。\n          <br>④ <b>没有分页组件</b>。\n          <br>另：<code>HomeViewModel</code> 里的 <code>PlaceholderPalette</code> 是\n          <b>20 个硬编码的 Material 色号 hex 数组</b>（注释写「封面图加载完成前显示的底色」），\n          它们是封面占位色、不属于令牌体系——建议改为按索引从\n          <code>--theme-10</code>…<code>--theme-90</code> 派生（迁移后即\n          <code>palette.rs</code> 的 <code>THEME_10..THEME_90</code>），\n          或明确记为「调试期占位色，发布前移除」。\n          <br><b>目标（GPUI）</b>：分页不用自己搭——选 <code>pagination::Pagination</code>；\n          「加载更多」用 <code>button::Button</code>（通栏 <code>w_full</code> + 虚线边）；\n          无限滚动与虚拟列表用 <code>v_virtual_list</code> / <code>list::List</code>\n          （原「容器池 + 按行节流」的职责改由 <code>v_virtual_list</code> 承担，见第 10 节）。\n          <b>需要自建的部分</b>：① 到底提示「已经到底了 · 共 N 条」（<code>empty::Empty</code>\n          可以复用其排版，但文案位置是列表尾部）；\n          ② <code>MaxItemCount = 200</code> 到顶后的「到底」出口属于业务状态，组件不提供。</div></div>\n    </div>\n  </div>\n\n  <!-- ================================================================== -->\n  <!-- 13.10 徽标 / 标签 / 头像 / 进度条                                     -->\n  <!-- ================================================================== -->\n  <div class=\"panel\">\n    <h3>13.10 徽标 / 标签 / 头像 / 进度条</h3>\n    <p class=\"note\">参考 <b>B 站网页版</b>（封面左上的「直播」粉色角标、右上的「会员」标、\n      底部的时长角标与观看进度条；UP 主头像为圆形）与 <b>YouTube 桌面版</b>（视频标题下方的\n      频道头像 + 订阅按钮）。取舍：YKPili 的角标只用<b>实心胶囊 + 白字</b>一种形态，\n      不做 B 站那种带描边的多态角标——桌面端尺寸小，多态角标会糊成一团。</p>\n\n    <div class=\"grid-2\">\n      <div>\n        <h3 style=\"font-size:var(--fs-control)\">几何规格</h3>\n        <table>\n          <thead><tr><th>元素</th><th>几何</th><th>圆角</th><th>配色</th><th>字号</th></tr></thead>\n          <tbody>\n            <tr><td>分类 pill</td><td class=\"mono\">h 22，左右 12</td><td class=\"mono\">9999</td>\n              <td class=\"mono\">默认 fill-2 / text-3；选中 theme-20 / theme-primary</td>\n              <td class=\"mono\">11 overlay</td></tr>\n            <tr><td>状态 tag</td><td class=\"mono\">h 18，左右 4</td><td class=\"mono\">9999</td>\n              <td class=\"mono\">按语义取 status-* 文字 + fill-2 底</td><td class=\"mono\">11 overlay</td></tr>\n            <tr><td>数字角标 / 严重度 chip</td><td class=\"mono\">h 18，最小宽 18</td><td class=\"mono\">9999</td>\n              <td class=\"mono\">theme-primary / text-on-accent</td><td class=\"mono\">10 micro</td></tr>\n            <tr><td>红点</td><td class=\"mono\">⌀6</td><td class=\"mono\">9999</td>\n              <td class=\"mono\">bili-pink</td><td class=\"mono\">—</td></tr>\n            <tr><td>封面数据层</td><td class=\"mono\">11px 文字 + 文字阴影</td><td class=\"mono\">—</td>\n              <td class=\"mono\">text-on-accent / 0 1px 3px 阴影</td><td class=\"mono\">11 overlay</td></tr>\n            <tr><td>UP 头像（卡片内）</td><td class=\"mono\">⌀18</td><td class=\"mono\">9999</td>\n              <td class=\"mono\">渐变 bili-blue → bili-pink，1px border-popover</td><td class=\"mono\">—</td></tr>\n            <tr><td>UP 头像（播放面板）</td><td class=\"mono\">⌀46</td><td class=\"mono\">9999</td>\n              <td class=\"mono\">同上</td><td class=\"mono\">—</td></tr>\n            <tr><td>观看进度条</td><td class=\"mono\">通栏 × 3</td><td class=\"mono\">9999</td>\n              <td class=\"mono\">轨道 fill-3；已看段 bili-pink</td><td class=\"mono\">—</td></tr>\n            <tr><td>通用进度条</td><td class=\"mono\">通栏 × 3</td><td class=\"mono\">9999</td>\n              <td class=\"mono\">轨道 fill-3；完成段 theme-primary</td><td class=\"mono\">—</td></tr>\n          </tbody>\n        </table>\n      </div>\n      <div>\n        <h3 style=\"font-size:var(--fs-control)\">使用位置</h3>\n        <table>\n          <thead><tr><th>元素</th><th>位置</th><th>来源</th></tr></thead>\n          <tbody>\n            <tr><td>直播角标</td><td>封面左上，<code>--space-2</code> 内缩</td><td>第 04 节卡片第 1 层</td></tr>\n            <tr><td>时长角标</td><td>封面右下，与播放量同行</td><td>第 04 节卡片第 2 层</td></tr>\n            <tr><td>观看进度条</td><td>封面最下沿，通栏</td><td>第 04 节卡片第 3 层</td></tr>\n            <tr><td>UP 头像</td><td>卡片署名行左，⌀18</td><td>第 04 节卡片第 6 层</td></tr>\n            <tr><td>分类 pill</td><td>顶栏下方吸顶导航</td><td>第 03 节</td></tr>\n            <tr><td>未读红点</td><td>顶栏消息图标右上角</td><td>第 03 节</td></tr>\n            <tr><td>标签（分区 / 话题）</td><td>播放浮窗信息面板底部</td><td>第 06 节</td></tr>\n          </tbody>\n        </table>\n        <div class=\"callout ok\" style=\"margin-top:12px\"><svg class=\"icon icon-sm ti\"><use href=\"#i-check\"></use></svg>\n          <div><b>字号阶已补齐（已裁决）。</b>主文档原先有 <b>8 处 11px</b> 与 <b>2 处 10px</b>\n            没进字号阶——这是第 02 节「视图不得硬编码尺寸」的破口。已补两档：\n            <code>--fs-micro 10</code>（角标 / 严重度 chip）与\n            <code>--fs-overlay 11</code>（封面数据层 / 状态标签 / 内联次要文字）。\n            本节<b>按新变量对齐</b>：角标与严重度 chip 用 <code>--fs-micro</code>，\n            状态标签 / 分类 pill / 封面数据层用 <code>--fs-overlay</code>；\n            <b>不把它们统一到 <code>--fs-caption 12</code></b>，以免破坏第 04 节\n            「封面数据层 11px + 文字阴影」的既有口径。</div></div>\n      </div>\n    </div>\n\n    <div class=\"s13-demo\" style=\"margin-top:16px\">\n      <div class=\"s13-col\">\n        <div class=\"s13-row s13-tight\">\n          <span class=\"s13-label\">分类 pill</span>\n          <span class=\"s13-pill\">动画</span>\n          <span class=\"s13-pill s13-active\">游戏</span>\n          <span class=\"s13-pill\">音乐</span>\n          <span class=\"s13-pill s13-danger\">已删除</span>\n        </div>\n        <div class=\"s13-row s13-tight\">\n          <span class=\"s13-label\">角标 / 红点</span>\n          <span class=\"s13-badge\">12</span>\n          <span class=\"s13-badge s13-danger\">99+</span>\n          <span class=\"s13-badge s13-dot\" aria-label=\"有 3 条未读消息\"></span>\n          <span class=\"s13-badge\">HOT</span>\n        </div>\n        <div class=\"s13-row s13-tight\">\n          <span class=\"s13-label\">头像</span>\n          <span class=\"s13-avatar s13-sm\" aria-label=\"UP 主头像\"></span>\n          <span class=\"s13-avatar\" aria-label=\"UP 主头像\"></span>\n          <span class=\"s13-avatar s13-lg\" aria-label=\"UP 主头像\"></span>\n        </div>\n        <div class=\"s13-col\" style=\"gap:var(--space-1)\">\n          <span class=\"s13-label\">观看进度条（已看 42%）</span>\n          <span class=\"s13-progress\"><span class=\"s13-progress-fill\" style=\"width:42%;display:block\"></span></span>\n          <span class=\"s13-label\">通用进度条（下载 78%）</span>\n          <span class=\"s13-progress s13-brand\"><span class=\"s13-progress-fill\" style=\"width:78%;display:block\"></span></span>\n        </div>\n      </div>\n    </div>\n\n    <div class=\"callout err\" style=\"margin-top:var(--space-3)\"><svg class=\"icon icon-sm ti\"><use href=\"#i-alert\"></use></svg>\n      <div><b>现状（Avalonia 债）与迁移后的目标。</b>\n        <b>这些元素在 XAML 侧全部不存在。</b>\n        <code>YKPili/Styles/Controls/</code> 目录当前只有 4 个文件\n        （<code>ButtonStyles</code> / <code>TextStyles</code> / <code>ScrollBarStyles</code> /\n        <code>GlassSurface</code>）+ <code>FluentOverrides</code>，\n        <b>没有任何 badge / pill / avatar / progress 样式类</b>；\n        主文档预览里的 <code>.tag</code> / <code>.sev</code> / <code>.avatar</code> /\n        <code>.thumb .progress</code> / <code>.thumb .badge-live</code> 都只是<b>文档演示样式</b>，\n        <code>YKPili/</code> 里没有任何一处引用。\n        <br>· <code>.thumb .badge-live</code> 在主文档里<b>只有定位没有外观</b>\n        （只有 <code>position/left/top</code>，没有背景色与尺寸）——直播角标的视觉规格尚不存在，\n        本节补齐为「粉色实心胶囊 + 白字 + 18 高」。\n        <br>· 进度条<b>颜色与几何</b>同样只在文档里，<code>YKPili/</code> 无对应实现。\n        <br>· <code>surfaces.rs</code> 里有 <code>IpTagBg</code> / <code>IpTagText</code>\n        两个为「IP 标签」预留的令牌，同样是<b>孤儿键</b>——迁移后直接复用\n        <code>tag::Tag</code> 的变体，<b>这两个孤儿键一并删除</b>。\n        <br><b>目标（GPUI）</b>：<code>badge::Badge</code>（数字角标 / 红点）、\n        <code>tag::{Tag, TagVariant}</code>（分类 pill / 状态 tag）、\n        <code>avatar::Avatar</code>（18 / 34 / 46 三档头像）、\n        <code>progress::Progress</code>（观看进度条 / 下载进度条）；\n        需要覆盖的主题字段是 <code>primary</code> / <code>danger</code> / <code>foreground</code>，\n        其余几何（pill 高 22、badge 高 18、红点 ⌀6、进度条高 3）用\n        <code>dimensions.rs</code> 的常量压在实例样式上。</div></div>\n  </div>\n\n  <!-- ================================================================== -->\n  <!-- 13.11 图标清单                                                       -->\n  <!-- ================================================================== -->\n  <div class=\"panel\">\n    <h3>13.11 图标清单</h3>\n    <p class=\"note\">主文档 sprite 实际包含 <b>45</b> 个 <code>&lt;symbol&gt;</code>\n      （<code>docs/ux-design-preview.html</code> 第 841–885 行），\n      契约 §1.5 列出的也是同一份清单。下表按用途分组列出<b>用途 / 尺寸档 / 使用位置</b>。\n      尺寸档规则：<code>icon-sm 16</code>（按钮内、行内）、\n      <code>icon-md 20</code>（工具栏、菜单）、\n      <code>icon-lg 24</code>（卡片、大尺寸按钮）、\n      <code>icon-xl 32</code>（空态 / 错误态的大图标）。\n      描边统一 1.6、线性、无 emoji。\n      <br><b>实现方式（GPUI，契约 §1.5）</b>：<b>45 个 id 一个都不删</b>——它们是设计资产；\n      实现改为 <code>svg()</code> 引用同目录的 SVG 文件，或用 <code>Icon::path(\"icons/xxx.svg\")</code>\n      / <code>Icon::data(bytes)</code> 引用内嵌数据，尺寸用 <code>Sizable</code>\n      （<code>xsmall</code> / <code>small</code> / <code>large</code>）或 <code>.size(px(n))</code> 指定。\n      <code>PathIcon</code> / <code>Svg.Skia</code> / <code>FontFamilyIcon</code> 这三条旧路线<b>全部作废</b>。</p>\n\n    <table>\n      <thead><tr><th>id</th><th>用途</th><th>尺寸档</th><th>使用位置</th></tr></thead>\n      <tbody>\n        <tr><td colspan=\"4\" style=\"background:var(--fill-1);color:var(--text-2);font-weight:var(--fw-semibold)\">导航与顶栏</td></tr>\n        <tr><td class=\"mono\">i-home</td><td>首页</td><td class=\"mono\">md 20</td><td>左侧 Dock 第 1 项</td></tr>\n        <tr><td class=\"mono\">i-trend</td><td>热门</td><td class=\"mono\">md 20</td><td>Dock 第 2 项 / 分类 tab</td></tr>\n        <tr><td class=\"mono\">i-grid</td><td>分区</td><td class=\"mono\">md 20</td><td>Dock 第 3 项</td></tr>\n        <tr><td class=\"mono\">i-trophy</td><td>排行</td><td class=\"mono\">md 20</td><td>Dock 第 4 项 / 分类 tab</td></tr>\n        <tr><td class=\"mono\">i-live</td><td>直播</td><td class=\"mono\">md 20</td><td>Dock 第 5 项 / 分类 tab / 直播角标</td></tr>\n        <tr><td class=\"mono\">i-star</td><td>个性推荐</td><td class=\"mono\">sm 16</td><td>分类 tab（默认选中）</td></tr>\n        <tr><td class=\"mono\">i-bell</td><td>动态 / 消息 / 正在关注</td><td class=\"mono\">sm 16 / md 20</td><td>顶栏消息按钮 / 分类 tab</td></tr>\n        <tr><td class=\"mono\">i-search</td><td>搜索</td><td class=\"mono\">sm 16 / md 20</td><td>顶栏搜索框左侧</td></tr>\n        <tr><td class=\"mono\">i-clock</td><td>稍后再看 / 历史</td><td class=\"mono\">md 20</td><td>顶栏 / 菜单项</td></tr>\n        <tr><td class=\"mono\">i-bookmark</td><td>收藏夹</td><td class=\"mono\">md 20</td><td>顶栏 / 菜单项</td></tr>\n        <tr><td class=\"mono\">i-refresh</td><td>刷新 / 历史记录</td><td class=\"mono\">sm 16 / md 20</td><td>空态按钮 / 顶栏</td></tr>\n        <tr><td class=\"mono\">i-tv</td><td>应用 Logo</td><td class=\"mono\">lg 24</td><td>顶栏品牌标</td></tr>\n        <tr><td class=\"mono\">i-layers</td><td>渲染引擎切换</td><td class=\"mono\">sm 16</td><td>文档顶栏分段控件</td></tr>\n        <tr><td class=\"mono\">i-moon</td><td>暗色主题</td><td class=\"mono\">sm 16</td><td>文档顶栏分段控件</td></tr>\n        <tr><td class=\"mono\">i-sun</td><td>亮色主题</td><td class=\"mono\">sm 16</td><td>文档顶栏分段控件</td></tr>\n\n        <tr><td colspan=\"4\" style=\"background:var(--fill-1);color:var(--text-2);font-weight:var(--fw-semibold)\">播放与互动</td></tr>\n        <tr><td class=\"mono\">i-play</td><td>播放（实心三角）</td><td class=\"mono\">md 20 / lg 24</td><td>播放浮窗中央按钮</td></tr>\n        <tr><td class=\"mono\">i-pause</td><td>暂停</td><td class=\"mono\">md 20</td><td>播放浮窗控制栏</td></tr>\n        <tr><td class=\"mono\">i-play-o</td><td>圆形播放（列表项）</td><td class=\"mono\">sm 16 / md 20</td><td>上下文菜单「在此处播放」</td></tr>\n        <tr><td class=\"mono\">i-danmaku</td><td>弹幕</td><td class=\"mono\">md 20</td><td>播放浮窗控制栏 / 弹幕开关</td></tr>\n        <tr><td class=\"mono\">i-cc</td><td>字幕</td><td class=\"mono\">md 20</td><td>播放浮窗控制栏</td></tr>\n        <tr><td class=\"mono\">i-speed</td><td>倍速</td><td class=\"mono\">md 20</td><td>播放浮窗控制栏 / 设置项</td></tr>\n        <tr><td class=\"mono\">i-vol</td><td>音量开</td><td class=\"mono\">md 20</td><td>播放浮窗控制栏</td></tr>\n        <tr><td class=\"mono\">i-vol-off</td><td>静音</td><td class=\"mono\">md 20</td><td>播放浮窗控制栏</td></tr>\n        <tr><td class=\"mono\">i-expand</td><td>画中画 / 全屏</td><td class=\"mono\">md 20</td><td>播放浮窗控制栏</td></tr>\n        <tr><td class=\"mono\">i-thumb</td><td>点赞</td><td class=\"mono\">md 20</td><td>播放浮窗信息面板互动行</td></tr>\n        <tr><td class=\"mono\">i-coin</td><td>投币</td><td class=\"mono\">md 20</td><td>播放浮窗信息面板互动行</td></tr>\n        <tr><td class=\"mono\">i-share</td><td>分享</td><td class=\"mono\">md 20</td><td>播放浮窗信息面板互动行</td></tr>\n        <tr><td class=\"mono\">i-chat</td><td>评论</td><td class=\"mono\">md 20</td><td>播放浮窗信息面板互动行</td></tr>\n        <tr><td class=\"mono\">i-eye</td><td>观看 / 播放量</td><td class=\"mono\">sm 16</td><td>封面数据层</td></tr>\n        <tr><td class=\"mono\">i-download</td><td>下载</td><td class=\"mono\">sm 16 / md 20</td><td>封面悬停操作 / 菜单项</td></tr>\n\n        <tr><td colspan=\"4\" style=\"background:var(--fill-1);color:var(--text-2);font-weight:var(--fw-semibold)\">通用动作与状态</td></tr>\n        <tr><td class=\"mono\">i-more</td><td>更多（三点）</td><td class=\"mono\">sm 16 / md 20 / lg 24</td><td>封面悬停操作 / 菜单触发 / 顶栏</td></tr>\n        <tr><td class=\"mono\">i-check</td><td>勾选 / 成功</td><td class=\"mono\">sm 16</td><td>复选框选中 / Toast 成功</td></tr>\n        <tr><td class=\"mono\">i-close</td><td>关闭</td><td class=\"mono\">sm 16 / md 20</td><td>Toast 关闭 / 对话框关闭</td></tr>\n        <tr><td class=\"mono\">i-minus</td><td>减号 / 收起</td><td class=\"mono\">md 20</td><td>倍速菜单 / 面板收起</td></tr>\n        <tr><td class=\"mono\">i-plus（与 §12 重复）</td><td>加号 / 展开</td><td class=\"mono\">md 20</td><td>倍速菜单 / 折叠面板</td></tr>\n        <tr><td class=\"mono\">i-chevron-left</td><td>左箭头</td><td class=\"mono\">sm 16</td><td>分页器 / 侧栏收起</td></tr>\n        <tr><td class=\"mono\">i-chevron-right</td><td>右箭头</td><td class=\"mono\">sm 16</td><td>分页器 / 侧栏展开</td></tr>\n        <tr><td class=\"mono\">i-chevron-down（与 §12 重复）</td><td>下箭头</td><td class=\"mono\">sm 16</td><td>下拉触发 / 展开更多</td></tr>\n        <tr><td class=\"mono\">i-chevron-up（本节新增）</td><td>上箭头</td><td class=\"mono\">sm 16</td><td>收起 / 回到顶部</td></tr>\n        <tr><td class=\"mono\">i-settings</td><td>设置</td><td class=\"mono\">md 20</td><td>顶栏 / 播放浮窗设置齿轮</td></tr>\n        <tr><td class=\"mono\">i-alert</td><td>提示 / 警告</td><td class=\"mono\">sm 16 / xl 32</td><td>Callout / 错误态 / 空态</td></tr>\n        <tr><td class=\"mono\">i-inbox</td><td>空态</td><td class=\"mono\">xl 32</td><td>空状态大图标</td></tr>\n        <tr><td class=\"mono\">i-wifi-off</td><td>离线</td><td class=\"mono\">xl 32</td><td>离线状态大图标 / 通知条</td></tr>\n        <tr><td class=\"mono\">i-ban</td><td>不感兴趣 / 屏蔽</td><td class=\"mono\">sm 16</td><td>菜单危险项</td></tr>\n        <tr><td class=\"mono\">i-trash（与 §12 重复）</td><td>删除</td><td class=\"mono\">sm 16 / md 20</td><td>危险按钮 / 危险菜单项</td></tr>\n        <tr><td class=\"mono\">i-copy（本节新增）</td><td>复制</td><td class=\"mono\">sm 16</td><td>菜单「复制链接」</td></tr>\n        <tr><td class=\"mono\">i-report（本节新增）</td><td>举报</td><td class=\"mono\">sm 16</td><td>菜单危险项「举报」</td></tr>\n\n        <tr><td colspan=\"4\" style=\"background:var(--fill-1);color:var(--text-2);font-weight:var(--fw-semibold)\">管理与列表</td></tr>\n        <tr><td class=\"mono\">i-list</td><td>列表视图</td><td class=\"mono\">md 20</td><td>视图切换</td></tr>\n        <tr><td class=\"mono\">i-pin</td><td>置顶</td><td class=\"mono\">md 20</td><td>收藏夹 / 稍后再看列表项</td></tr>\n        <tr><td class=\"mono\">i-edit</td><td>编辑</td><td class=\"mono\">md 20</td><td>列表项右键菜单</td></tr>\n        <tr><td class=\"mono\">i-arrow-up</td><td>置顶 / 回到顶部</td><td class=\"mono\">md 20</td><td>回到顶部按钮</td></tr>\n        <tr><td class=\"mono\">i-user（与 §12 重复）</td><td>用户 / UP 主</td><td class=\"mono\">md 20</td><td>头像占位 / 关注列表</td></tr>\n        <tr><td class=\"mono\">i-image（本节新增）</td><td>图片</td><td class=\"mono\">md 20 / xl 32</td><td>封面加载失败占位</td></tr>\n        <tr><td class=\"mono\">i-sort（与 §12 重复）</td><td>排序</td><td class=\"mono\">md 20</td><td>列表排序切换</td></tr>\n        <tr><td class=\"mono\">i-filter（与 §12 重复）</td><td>筛选</td><td class=\"mono\">md 20</td><td>列表筛选</td></tr>\n        <tr><td class=\"mono\">i-loop（本节新增）</td><td>循环播放</td><td class=\"mono\">md 20</td><td>播放浮窗控制栏</td></tr>\n        <tr><td class=\"mono\">i-pip（本节新增）</td><td>画中画</td><td class=\"mono\">md 20</td><td>播放浮窗控制栏</td></tr>\n        <tr><td class=\"mono\">i-logout（本节新增）</td><td>退出登录</td><td class=\"mono\">md 20</td><td>头像菜单底部</td></tr>\n        <tr><td class=\"mono\">i-help（本节新增）</td><td>帮助</td><td class=\"mono\">md 20</td><td>头像菜单 / 设置页</td></tr>\n        <tr><td class=\"mono\">i-info（与 §12 重复）</td><td>信息</td><td class=\"mono\">sm 16 / xl 32</td><td>信息型 Toast / 空态</td></tr>\n      </tbody>\n    </table>\n\n    <div class=\"grid-2\" style=\"margin-top:16px\">\n      <div class=\"panel\" style=\"margin:0\">\n        <h3 style=\"font-size:var(--fs-control)\">建议新增图标预览（15 个：8 本节新增 + 7 与第 12 节重复）</h3>\n        <p class=\"s13-note\" style=\"margin:var(--space-2) 0\">\n          <b>本片段不再重复定义 symbol</b>：主文档只允许存在一份 sprite，\n          同 id 出现两次会有歧义。以下 id 的图形本体由 Lead 统一合并进主文档的\n          <code>&lt;defs&gt;</code> 块，<b>合并前此处预览为空属预期</b>。</p>\n        <div class=\"s13-row s13-tight\" style=\"gap:var(--space-4)\">\n          <span class=\"s13-icon-cell\"><span class=\"s13-icon-box\"><svg class=\"icon icon-md\"><use href=\"#i-plus\"></use></svg></span><span class=\"s13-label\">plus</span></span>\n          <span class=\"s13-icon-cell\"><span class=\"s13-icon-box\"><svg class=\"icon icon-md\"><use href=\"#i-chevron-down\"></use></svg></span><span class=\"s13-label\">chevron-down</span></span>\n          <span class=\"s13-icon-cell\"><span class=\"s13-icon-box\"><svg class=\"icon icon-md\"><use href=\"#i-chevron-up\"></use></svg></span><span class=\"s13-label\">chevron-up</span></span>\n          <span class=\"s13-icon-cell\"><span class=\"s13-icon-box\"><svg class=\"icon icon-md\"><use href=\"#i-trash\"></use></svg></span><span class=\"s13-label\">trash</span></span>\n          <span class=\"s13-icon-cell\"><span class=\"s13-icon-box\"><svg class=\"icon icon-md\"><use href=\"#i-copy\"></use></svg></span><span class=\"s13-label\">copy</span></span>\n          <span class=\"s13-icon-cell\"><span class=\"s13-icon-box\"><svg class=\"icon icon-md\"><use href=\"#i-report\"></use></svg></span><span class=\"s13-label\">report</span></span>\n          <span class=\"s13-icon-cell\"><span class=\"s13-icon-box\"><svg class=\"icon icon-md\"><use href=\"#i-user\"></use></svg></span><span class=\"s13-label\">user</span></span>\n          <span class=\"s13-icon-cell\"><span class=\"s13-icon-box\"><svg class=\"icon icon-md\"><use href=\"#i-image\"></use></svg></span><span class=\"s13-label\">image</span></span>\n          <span class=\"s13-icon-cell\"><span class=\"s13-icon-box\"><svg class=\"icon icon-md\"><use href=\"#i-sort\"></use></svg></span><span class=\"s13-label\">sort</span></span>\n          <span class=\"s13-icon-cell\"><span class=\"s13-icon-box\"><svg class=\"icon icon-md\"><use href=\"#i-filter\"></use></svg></span><span class=\"s13-label\">filter</span></span>\n          <span class=\"s13-icon-cell\"><span class=\"s13-icon-box\"><svg class=\"icon icon-md\"><use href=\"#i-loop\"></use></svg></span><span class=\"s13-label\">loop</span></span>\n          <span class=\"s13-icon-cell\"><span class=\"s13-icon-box\"><svg class=\"icon icon-md\"><use href=\"#i-pip\"></use></svg></span><span class=\"s13-label\">pip</span></span>\n          <span class=\"s13-icon-cell\"><span class=\"s13-icon-box\"><svg class=\"icon icon-md\"><use href=\"#i-logout\"></use></svg></span><span class=\"s13-label\">logout</span></span>\n          <span class=\"s13-icon-cell\"><span class=\"s13-icon-box\"><svg class=\"icon icon-md\"><use href=\"#i-help\"></use></svg></span><span class=\"s13-label\">help</span></span>\n          <span class=\"s13-icon-cell\"><span class=\"s13-icon-box\"><svg class=\"icon icon-md\"><use href=\"#i-info\"></use></svg></span><span class=\"s13-label\">info</span></span>\n        </div>\n        <table style=\"margin-top:var(--space-3)\">\n          <thead><tr><th>归属</th><th>id</th><th>处理方式</th></tr></thead>\n          <tbody>\n            <tr><td><span class=\"tag ghost\">与第 12 节重复</span></td>\n              <td class=\"mono\">i-plus, i-chevron-down, i-trash, i-user, i-sort, i-filter, i-info</td>\n              <td>取全局合并后的<b>唯一定义</b>（图形以合并结果为准，本节不改图形）</td></tr>\n            <tr><td><span class=\"tag ok\">本节新增</span></td>\n              <td class=\"mono\">i-chevron-up, i-copy, i-report, i-image, i-loop, i-pip, i-logout, i-help</td>\n              <td>由 Lead 合并进主文档 sprite，路径数据见 NOTES「二」</td></tr>\n          </tbody>\n        </table>\n      </div>\n      <div class=\"callout err\"><svg class=\"icon icon-sm ti\"><use href=\"#i-alert\"></use></svg>\n        <div><b>与项目现状的差距（两条，都是硬缺口）。</b>\n          <br>① <b>数量对不上</b>：本节任务书写的是「48 个 id」，\n          但主文档 sprite <b>实际只有 45 个</b>（<code>grep 'symbol id=\"i-'</code> 命中 45 行，\n          文件第 841–885 行），契约 §1.5 的清单也是这 45 个。\n          本表以<b>真实代码为准</b>列 45 个既有 + 15 个建议新增。\n          <br>② <b>id 与第 12 节重复 7 个</b>：<code>i-user</code> / <code>i-sort</code> /\n          <code>i-filter</code> / <code>i-trash</code> / <code>i-plus</code> / <code>i-info</code> /\n          <code>i-chevron-down</code> 两节都定义了（图形还不一样）。\n          取<b>全局合并后的唯一定义</b>，本节不改图形；其余 8 个为<b>本节新增</b>。\n          <br>③ <b>GPUI 原生支持 SVG</b>（契约 §1.5）：<code>gpui::svg()</code> 直接渲染 SVG 资源，\n          组件库另有 <code>Icon</code> 类型与 <code>icon_named!</code> 宏。\n          因此落地方式只有一条：<b>把 45+15 个 symbol 落成 SVG 文件</b>，\n          用 <code>Icon::path(\"icons/xxx.svg\")</code> 或 <code>Icon::data(bytes)</code> 引用；\n          跨平台字形不一致的字体图标路线<b>不再讨论</b>。\n          <br><b>仍需 Lead 处理的部分</b>：① <b>45 个既有 id 是设计资产，一个都不能删</b>，\n          它们要逐个导出成 SVG 文件并登记在 <code>app/crates/yk-ui/src/icons.rs</code>；\n          ② 本节新增的 8 个 id 的路径数据（NOTES 二.B 已给出）同样导出成文件；</div></div>\n    </div>\n  </div>\n\n  <!-- ================================================================== -->\n  <!-- 补充 sprite 块已按 Lead 裁决移除：                                    -->\n  <!-- 主文档只允许存在一份 sprite 定义，同 id 的 <symbol> 出现两次会有歧义。 -->\n  <!-- 本节新增 / 重复的 15 个 id 的图形定义见文件末尾 NOTES「二、图标 id 清单」， -->\n  <!-- 由 Lead 统一合并进主文档 sprite（docs/ux-design-preview.html 的 <defs> 块）。 -->\n  <!-- ================================================================== -->\n\n  <!-- ================================================================== -->\n  <!-- 13.12 组件落地映射                                                   -->\n  <!-- ================================================================== -->\n  <div class=\"panel\">\n    <h3>13.12 组件落地映射</h3>\n    <p class=\"note\"><b>本表是本节唯一的落地口径。</b>GPUI 下<b>没有样式文件、没有\n      <code>StyleInclude</code>、没有资源字典</b>（契约 §1.1 / §6.1）——\n      所以「新建 9 个 <code>Styles/Controls/*.axaml</code>」这整套施工方式作废，\n      每一行只回答三件事：<b>用哪个 <code>gpui-component</code> 模块</b>、\n      <b>覆盖哪些主题字段</b>、<b>哪些部分必须自建</b>。\n      模块名全部来自 <code>gpui-component-0.7.3/src/lib.rs</code> 的 <code>pub mod</code>；\n      标「待核实」的只剩附录 E 的 3 条；其余组件结论已归档在下方「组件能力核实结论」。</p>\n    <table>\n      <thead><tr><th>组件</th><th><code>gpui-component</code> 模块</th><th>需覆盖的主题字段</th><th>需自建的部分</th></tr></thead>\n      <tbody>\n        <tr><td>按钮</td>\n          <td class=\"mono\">button::Button<br>（<code>ButtonVariant</code> / <code>ButtonRounded</code> / <code>Sizable</code>）</td>\n          <td><code>primary</code>（accent 底）/ <code>danger</code> / <code>foreground</code> /\n            <code>ring</code>；胶囊半径走 <code>Theme::radius_full()</code></td>\n          <td>28 / 34 / 40 三档高度（<code>Size::Size(px(n))</code> 或 <code>.h(px(n))</code>）；\n            图标按钮热区 = 该档高度；顶栏图标按钮 38</td></tr>\n        <tr><td>输入框</td>\n          <td class=\"mono\">input::{Input, InputState}</td>\n          <td><code>foreground</code> / <code>muted_foreground</code>（占位）/ <code>border</code> /\n            <code>ring</code> / <code>danger</code>；圆角走 <code>Theme.radius</code></td>\n          <td>错误文案行（caption 12 + <code>i-alert</code>）、字数统计行；\n            错误态与文案的无障碍关联</td></tr>\n        <tr><td>菜单</td>\n          <td class=\"mono\">menu::{PopupMenu, ContextMenu}<br>（另 <code>native_menu::NativeMenu</code> 可接系统菜单）</td>\n          <td><code>popover</code>（面板底，配成 Strong 0.92）/ <code>border</code> / <code>foreground</code></td>\n          <td>行高 32 / 最小宽 160 / 图标槽 16+20 / 分隔线上下 4；\n            「禁用项仍可聚焦」的键盘行为；贴边翻转定位（E-8，见 13.3.1）</td></tr>\n        <tr><td>对话框</td>\n          <td class=\"mono\">dialog::{Dialog, DialogButtonProps, DialogFooter}<br>+\n            <code>WindowExt::{open_dialog, open_alert_dialog}</code></td>\n          <td><code>popover</code> / <code>overlay</code>（遮罩）/ <code>radius_lg</code>（24）/ <code>ring</code></td>\n          <td>危险确认的初始焦点落「取消」（随无障碍暂缓，第 10 节）；\n            自解释按钮文案属内容层</td></tr>\n        <tr><td>Toast</td>\n          <td class=\"mono\">notification::{Notification, NotificationSettings, NotificationType}<br>+\n            <code>WindowExt::push_notification</code></td>\n          <td><code>NotificationSettings.{placement, width, max_items, margins}</code>；\n            色走 <code>popover</code> / <code>border</code> / <code>success</code> /\n            <code>info</code> / <code>warning</code> / <code>danger</code></td>\n          <td>四档停留时长的计时（组件内部固定 5s）；同类型多条合并为「×N」</td></tr>\n        <tr><td>Tooltip</td>\n          <td class=\"mono\">tooltip::Tooltip<br>（<code>show_delay</code> + <code>ManagedTooltipExt</code>）</td>\n          <td><code>popover</code> / <code>border</code> / <code>foreground</code></td>\n          <td>最大宽 240 可用 <code>.max_w</code> 覆盖；箭头 8×8 <b>未内建</b>，需自绘；\n            键盘聚焦时立即显示（不等 500ms）</td></tr>\n        <tr><td>开关</td>\n          <td class=\"mono\">switch::Switch</td>\n          <td><code>primary</code>（开态）/ <code>switch</code>（关态轨道）/\n            <code>switch_thumb</code>（滑块）；<code>ring</code></td>\n          <td>文档仅 small 28×16 / medium 36×20，<b>44×24 未提供</b>（E-5）</td></tr>\n        <tr><td>滑块</td>\n          <td class=\"mono\">slider::Slider</td>\n          <td><code>primary</code>（已播放段）；轨道底色走项目扩展 <code>fill_3</code>；<code>ring</code></td>\n          <td>文档未给轨道 / thumb 几何（E-5，源码默认 6 / 16）；\n            只读的观看进度条改用 <code>progress::Progress</code>，不要用 Slider</td></tr>\n        <tr><td>复选 / 单选</td>\n          <td class=\"mono\">checkbox::Checkbox<br>radio::{Radio, RadioGroup}</td>\n          <td><code>primary</code>（选中）/ <code>border</code>（描边）/ <code>ring</code></td>\n          <td>文档按字号档，无 16 固定值（E-5，默认约 16）</td></tr>\n        <tr><td>滚动条</td>\n          <td class=\"mono\">scroll 模块<br>（<code>Scrollable</code> + <code>ScrollbarMode</code>）</td>\n          <td><code>scrollbar</code>（滑块色）；<code>Theme.scrollbar_mode</code></td>\n          <td>可配（E-4）：base <code>ScrollbarStyles</code> 的 width / min_length / hover；默认 6 / 48，设 24 即可</td></tr>\n        <tr><td>分页 / 加载更多 / 无限滚动</td>\n          <td class=\"mono\">pagination::Pagination<br>list::List<br><code>v_virtual_list</code></td>\n          <td><code>foreground</code> / <code>primary</code>（当前页）/ <code>muted_foreground</code></td>\n          <td>「加载更多」通栏虚线按钮；「已经到底了 · 共 N 条」尾注；\n            200 条上限的业务出口</td></tr>\n        <tr><td>徽标 / 标签 / 头像 / 进度</td>\n          <td class=\"mono\">badge::Badge / tag::{Tag, TagVariant}<br>avatar::Avatar /\n            progress::{Progress, ProgressCircle}</td>\n          <td><code>primary</code> / <code>danger</code> / <code>foreground</code></td>\n          <td>pill 高 22 / badge 高 18 / 红点 ⌀6 / 头像 18·34·46 / 进度条高 3</td></tr>\n        <tr><td>骨架 / 空态</td>\n          <td class=\"mono\">skeleton::Skeleton<br>empty::{Empty, EmptyHeader, EmptyMedia,\n            EmptyTitle, EmptyDescription, EmptyContent}</td>\n          <td><code>skeleton</code> / <code>muted_foreground</code> / <code>foreground</code></td>\n          <td>骨架必须复刻真实单元格几何（208×184）；四类空态文案</td></tr>\n        <tr><td>图标</td>\n          <td class=\"mono\"><code>svg()</code> + <code>Icon</code><br>（<code>Icon::path</code> /\n            <code>Icon::data</code> / <code>icon_named!</code> / <code>gpui_kit_assets::IconName</code>）</td>\n          <td><b>无</b>——颜色用 <code>.text_color(cx.theme()....)</code> 指定</td>\n          <td>45 个既有图标落成 SVG 资源文件 + 60 个 id 的注册表\n            （<code>app/crates/yk-ui/src/icons.rs</code>）</td></tr>\n        <tr><td>玻璃材质</td>\n          <td class=\"mono\">元素链式样式<br>（<code>.bg()</code> + <code>.border_1()</code> +\n            <code>.shadow(Vec&lt;BoxShadow&gt;)</code>）</td>\n          <td>项目扩展：<code>surface_elevated_strong</code> / <code>border_popover</code> /\n            <code>shadow_glass_elevated</code> / <code>shadow_glass_modal</code> / <code>edge_glow</code></td>\n          <td>四层叠加封装成 <code>const</code> 或 <code>trait YkStyled</code> 方法\n            （<code>app/crates/yk-ui/src/styled.rs</code>）</td></tr>\n        <tr><td>主题与令牌</td>\n          <td class=\"mono\">theme::{Theme, ThemeColor, ThemeMode}<br>（<code>Theme::update</code> /\n            <code>cx.theme()</code>）</td>\n          <td>第一层映射见契约 §3（<code>primary</code> / <code>foreground</code> /\n            <code>muted_foreground</code> / <code>background</code> / <code>popover</code> /\n            <code>border</code> / <code>skeleton</code> / <code>overlay</code> /\n            <code>ring</code> / 状态色）；第二层为 <code>YkSurfaces</code> 扩展字段</td>\n          <td><code>app/crates/yk-ui/src/theme/</code> 六个模块（\n            <code>mod.rs</code> / <code>palette.rs</code> / <code>surfaces.rs</code> /\n            <code>typography.rs</code> / <code>dimensions.rs</code> / <code>motion.rs</code>）+\n            <code>shadows.rs</code></td></tr>\n        <tr><td>行为时长</td>\n          <td class=\"mono\">theme::MotionTokens<br>（<code>Theme.motion</code>）+ <code>animation</code></td>\n          <td><code>Theme.motion</code> 的语义时长 / 缓动</td>\n          <td>Tooltip 延迟 500ms 与 Toast 停留四档是<b>行为时长</b>，不是过渡时长，\n            落在 <code>app/crates/yk-ui/src/theme/motion.rs</code></td></tr>\n      </tbody>\n    </table>\n  </div>\n\n  <!-- ================================================================== -->\n  <!-- 13.13 无障碍基线                                                     -->\n  <!-- ================================================================== -->\n  <div class=\"panel\">\n    <h3>13.13 无障碍基线</h3>\n    <p class=\"note\">本节是第 10 节「无障碍与性能」在<b>组件层</b>的落地细则：\n      第 10 节定原则，本节定<b>每个组件的具体属性值</b>。</p>\n\n    <div class=\"grid-2\">\n      <div>\n        <h3 style=\"font-size:var(--fs-control)\">焦点环 · 键盘顺序</h3>\n        <table>\n          <thead><tr><th>项</th><th>规格</th></tr></thead>\n          <tbody>\n            <tr><td>焦点环</td><td class=\"mono\">0 0 0 3px var(--theme-30) + inset 0 0 0 1px var(--theme-60)\n              （<b>与第 09 节统一口径一致</b>）<br>\n              GPUI 写法：两段 <code>BoxShadow</code> —— 外段\n              <code>BoxShadow::new(px(0.), px(0.), theme_30).spread_radius(px(3.))</code>、\n              内段 <code>BoxShadow::new(px(0.), px(0.), theme_60).spread_radius(px(1.)).inset()</code>；\n              <b>组件库自带</b>（<code>Theme.focus_ring</code> + <code>ThemeColor.ring</code> +\n              各组件的 <code>FocusLine</code>），自建元素才手写这两段</td></tr>\n            <tr><td>生效时机</td><td class=\"mono\">键盘导航时出现，鼠标点击不出现\n              （原 <code>:focus-visible</code> 语义；GPUI 的 <code>Theme.focus_ring</code>\n              文档只保证 focused 时显示，未提键盘/指针区分；<b>随无障碍暂缓（第 10 节，E-3）</b>）</td></tr>\n            <tr><td>圆角跟随</td><td class=\"mono\">与宿主同半径（胶囊按钮 → 胶囊焦点环）</td></tr>\n            <tr><td>对比度</td><td class=\"mono\">焦点环与相邻底色 ≥ 3:1</td></tr>\n            <tr><td>Tab 顺序</td><td class=\"mono\">= 视觉顺序 = 元素树顺序，三者必须一致</td></tr>\n            <tr><td>浮层打开</td><td class=\"mono\">焦点陷阱在浮层内；关闭后归还触发元素</td></tr>\n            <tr><td>浮层关闭</td><td class=\"mono\">Esc（菜单 / Tooltip / 对话框）→ 归还焦点</td></tr>\n            <tr><td>网格导航</td><td class=\"mono\">↑↓←→ 按行列移动，Enter 播放（第 09 节）</td></tr>\n            <tr><td>滚动容器</td><td class=\"mono\">可聚焦，支持 PageUp / PageDown / Home / End</td></tr>\n            <tr><td>全局键位总表</td><td class=\"mono\">见第 14 节统一收口；本节只定义组件级键盘模型</td></tr>\n          </tbody>\n        </table>\n      </div>\n      <div>\n        <h3 style=\"font-size:var(--fs-control)\">aria-* 映射（语义表）</h3>\n        <p class=\"note\">下表是<b>语义</b>要求，与实现框架无关。GPUI 侧的对应 API 是\n          <code>Role</code> / <code>accessibility_label</code> / <code>aria_label</code>\n          （<code>Button::accessibility_label</code> 等组件方法），\n          到 macOS / Windows 无障碍树的逐条映射<b>暂缓（第 10 节，E-9）</b>。</p>\n        <table>\n          <thead><tr><th>组件</th><th>role</th><th>必备状态 / 属性</th></tr></thead>\n          <tbody>\n            <tr><td>按钮</td><td class=\"mono\">button（原生）</td><td class=\"mono\">aria-label（仅图标按钮）</td></tr>\n            <tr><td>输入框</td><td class=\"mono\">textbox</td>\n              <td class=\"mono\">aria-label / aria-invalid / aria-describedby</td></tr>\n            <tr><td>菜单</td><td class=\"mono\">menu / menuitem / separator</td>\n              <td class=\"mono\">aria-haspopup / aria-expanded / aria-disabled / aria-checked（勾选型）</td></tr>\n            <tr><td>对话框</td><td class=\"mono\">dialog（危险确认用 alertdialog）</td>\n              <td class=\"mono\">aria-modal=true / aria-labelledby</td></tr>\n            <tr><td>Toast</td><td class=\"mono\">status（错误用 alert）</td>\n              <td class=\"mono\">aria-live=polite / assertive</td></tr>\n            <tr><td>Tooltip</td><td class=\"mono\">tooltip</td><td class=\"mono\">aria-describedby（挂在触发元素上）</td></tr>\n            <tr><td>开关</td><td class=\"mono\">switch</td><td class=\"mono\">aria-checked</td></tr>\n            <tr><td>复选框</td><td class=\"mono\">checkbox</td><td class=\"mono\">aria-checked / aria-disabled</td></tr>\n            <tr><td>单选</td><td class=\"mono\">radio / radiogroup</td><td class=\"mono\">aria-checked</td></tr>\n            <tr><td>滑块</td><td class=\"mono\">slider</td><td class=\"mono\">aria-valuenow / min / max / valuetext</td></tr>\n            <tr><td>进度条</td><td class=\"mono\">progressbar</td><td class=\"mono\">aria-valuenow / min / max</td></tr>\n            <tr><td>分页</td><td class=\"mono\">navigation</td><td class=\"mono\">aria-label（当前页用 aria-current=\"page\"）</td></tr>\n          </tbody>\n        </table>\n      </div>\n    </div>\n\n    <div class=\"grid-2\" style=\"margin-top:16px\">\n      <div class=\"callout info\"><svg class=\"icon icon-sm ti\"><use href=\"#i-alert\"></use></svg>\n        <div><b>对比度要求（两套主题分别测，不靠推断）。</b>\n          ① 正文 ≥ <b>4.5:1</b>，次要文字 ≥ <b>3:1</b>，大字（≥18.66px 或 14px 加粗）≥ <b>3:1</b>。\n          ② 焦点环与相邻底色 ≥ <b>3:1</b>。\n          ③ 非文本控件边界（输入框描边、滑块轨道）≥ <b>3:1</b>。\n          ④ 禁用控件豁免 WCAG 1.4.3——但仍应做到「看得出是禁用」，\n          本节用 <code>--fill-1</code> 底 + <code>--text-4</code> 字。\n          ⑤ 状态色作<b>文字</b>使用时按 4.5:1 校验：\n          <code>--status-success</code> 在亮色主题下偏浅，\n          小字号时建议改用「<code>--status-success</code> 文字 + <code>--fill-2</code> 底」而非实色底白字。</div></div>\n      <div class=\"callout warn\"><svg class=\"icon icon-sm ti\"><use href=\"#i-alert\"></use></svg>\n        <div><b>硬性底线（违反即返工）。</b>\n          ① <b>信息不靠颜色单独传达</b>：危险项 / 错误态 / 直播角标必须有图标或文字。\n          ② <b>键盘可达</b>：所有鼠标可点元素必须有对应键盘路径，\n          右键菜单必须有 <code>Shift+F10</code> 唤出路径。\n          ③ <b>焦点始终可见</b>：不允许 <code>outline: none</code> 而不给替代。\n          ④ <b>尊重系统的「减少动效」偏好</b>：关闭 Toast 淡入淡出、\n          按钮 <code>scale</code> 按压反馈、卡片悬停抬升。\n          GPUI 侧动效走 <code>animation</code> / <code>with_animation</code> 与\n          <code>Theme.motion</code>；「是否随系统减少动效开关一起降级」<b>已满足</b>\n          （<code>AnimationExt</code> 自动读取 <code>App::reduce_motion</code>，见 F.3 L-11）。\n          ⑤ <b>尊重系统动态字体</b>：卡片标题放大后仍保持 2 行截断不溢出\n          （GPUI 的 <code>Theme.font_size</code> + <code>rem</code> 缩放，文本截断靠\n          <code>line_clamp(2)</code> 一类约束，<b>随无障碍暂缓（第 10 节，E-11）</b>）。\n          ⑥ <b>目标尺寸 ≥ 24×24</b>（WCAG 2.2 Target Size Minimum），\n          主操作 ≥ 34（<code>--control-h</code>）。</div></div>\n    </div>\n  </div>\n  <div class=\"panel\" style=\"margin-top:16px\">\n    <h3>组件能力核实结论（已归档，2026-10）</h3>\n    <table>\n      <thead><tr><th>#</th><th>项</th><th>结论</th></tr></thead>\n      <tbody>\n        <tr><td class=\"mono\">E-1</td><td>Notification 自动消失</td>\n          <td>默认 <code>autohide(true)</code> 5s；悬停 / 键盘焦点时暂停，离开后继续。\n            <b>直接用它，不自己计时</b>；需要 2s/3s 档时再包一层。</td></tr>\n        <tr><td class=\"mono\">E-2</td><td>Input 错误槽 / ARIA</td>\n          <td>无内建 error 槽或 <code>aria-invalid</code>；错误展示自建\n            （<code>InputGroup.invalid(true)</code> + 外层文案）。ARIA 移到\n            <a href=\"#a11y\">第 10 节</a>暂缓。</td></tr>\n        <tr><td class=\"mono\">E-4</td><td>滚动条宽度 / 最小长度</td>\n          <td>base <code>ScrollbarStyles</code> 可配 track/thumb 的 width、min_length、\n            inset、radius 与 hover/active；默认 thumb 6、最小 48，显式设 24 即可。</td></tr>\n        <tr><td class=\"mono\">E-5</td><td>组件几何覆盖</td>\n          <td>avatar 可用 <code>.with_size(px(n))</code> 精确设 18/34/46；tooltip 可用\n            <code>.max_w(240)</code>。switch 文档只有 small 28×16 / medium 36×20；\n            slider/checkbox/radio/tag/badge 目标几何未提供，按各自退路走。</td></tr>\n        <tr><td class=\"mono\">E-8</td><td>popover / menu / tooltip 贴边翻转</td>\n          <td>tooltip / select / combobox 走 <code>Positioner::side</code>，<b>自动翻</b>到对侧；\n            <code>Popover</code>（corner，含按钮下拉菜单）与 <code>ContextMenu</code> / 子菜单\n            （<code>anchored()</code> + snap）<b>只 clamp 不翻</b>。\n            菜单/气泡统一改用 <code>Positioner::side</code> 承载，方案与验收见\n            <a href=\"#e8-flip\">13.3.1</a>。</td></tr>\n        <tr><td class=\"mono\">E-10</td><td>开关关态轨道色字段</td>\n          <td>关态 <code>ThemeColor.switch</code>、滑块 <code>switch_thumb</code>、开态\n            <code>primary</code>；<code>Switch</code> 读 <code>tokens.switch</code>，\n            改 <code>colors</code> 会同步。项目已映射，见 <a href=\"#e10-switch\">13.7</a>。</td></tr>\n        <tr><td class=\"mono\">E-12</td><td>图片缓存淘汰</td>\n          <td>公开 <code>ImageCache</code> + <code>ImageCacheItem</code> +\n            <code>cx.drop_image</code>；默认缓存用 <code>ImageSource::remove_asset</code>\n            删条目。方案见 <a href=\"#e12-image\">第 10 节性能</a>。</td></tr>\n      </tbody>\n    </table>\n  </div>\n</section>"};
